import { QURAN_DATA, QURAN_READING_LIBRARY, QURAN_CANONICAL_STATUS, BASMALAH_ARABIC, getReadingUnit, getReadingUnitAyat } from "./data/quran-canonical.js?v=3.27.0";
import { modules, sidebarOrder, moduleForPath } from './modules.js';
import { duaaCollections, duaaOrder, orderedItems, isComplete, completedCount, isMemorized, memorizedCount, totalMemorizedCount, totalUniqueDuaaCount, worshipToday, weekStatus, readingPreferences, duaaHistoryRecords, duaaHistorySummary } from './duaa.js';
import { APP_VERSION } from './version.js';
import { sourcesByIds } from './data/source-library.js';
import { resourcesByIds } from './data/resource-library.js';
import { NAMES_OF_ALLAH, nameById } from './data/names-of-allah.js?v=3.27.0';

const esc=(v='')=>String(v).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#039;');
const routeParts=(p)=>p.split('/').filter(Boolean);
const isReader=(p)=>/^\/duaa\/[^/]+\/read\/[^/]+(?:\/study\/[^/]+)?\/?$/.test(p)||/^\/quran\/(?:reading-unit|classic|featured-readings|navigator)\//.test(p)||/^\/quran\/al-kahf-friday\/section\/\d+$/.test(p)||/^\/quran\/al-mulk\/section\/\d+$/.test(p)||/^\/quran\/as-sajdah\/section\/\d+$/.test(p)||p==='/ramadan/reading';

function sidebar(active){return `<nav class="sidebar-nav" aria-label="Primary navigation">${sidebarOrder.map(id=>{const x=modules[id],a=x.id===active.id;return `<a class="sidebar-link${a?' is-active':''}" href="${x.navigation[0].route}" data-route>${x.icon}<span>${esc(x.shortLabel)}</span></a>`}).join('')}</nav>`}
function moduleNav(active,pathname){return `<nav class="module-nav-bar" aria-label="${esc(active.label)} navigation">${active.navigation.map(item=>{let a=pathname===item.route||(item.route==='/duaa'&&pathname==='/duaa');if(item.route==='/duaa/collections'&&['travel','weather','prayer','istikharah','food','clothing','anxiety','quranic'].some(id=>pathname===`/duaa/${id}`||pathname.startsWith(`/duaa/${id}/`)))a=true;if(['/duaa/morning','/duaa/evening','/duaa/sleep'].includes(item.route)&&pathname.startsWith(item.route+'/'))a=true;if(active.id==='prayer'&&item.route!=='/prayer'&&pathname.startsWith(item.route+'/'))a=true;if(active.id==='names'&&item.route!=='/names'&&pathname.startsWith(item.route+'/'))a=true;return `<a class="module-nav-link${a?' is-active':''}" href="${item.route}" data-route>${esc(item.label)}</a>`}).join('')}</nav>`}

function infoTip(label,text){return `<span class="info-tip"><button type="button" class="info-tip-button" aria-label="${esc(label)}">i</button><span class="info-tip-bubble" role="tooltip">${esc(text)}</span></span>`}
function pageEpigraph({quote='',citation='',context='',detail='',externalLink=''}={}){
  if(!quote||!citation)return '';
  const citationLines=Array.isArray(citation)?citation:[citation];
  const externalUrl=typeof externalLink==='string'?externalLink:externalLink?.url||'';
  const externalLabel=typeof externalLink==='object'&&externalLink?.label?externalLink.label:'Source';
  const external=externalUrl?`<p class="page-epigraph-source"><a class="page-epigraph-link" href="${esc(externalUrl)}" target="_blank" rel="noopener noreferrer"><span>${esc(externalLabel)}</span><i class="ph ph-arrow-square-out" aria-hidden="true"></i><span class="sr-only"> (opens in a new tab)</span></a></p>`:'';
  return `<aside class="page-epigraph" aria-label="Page introduction quotation"><blockquote>${context?`<p class="page-epigraph-context">${esc(context)}</p>`:''}<p class="page-epigraph-quote">${esc(quote)}</p><div class="page-epigraph-citation">${citationLines.filter(Boolean).map(line=>`<cite>${esc(line)}</cite>`).join('')}</div>${detail?`<p class="page-epigraph-detail">${esc(detail)}</p>`:''}${external}</blockquote><div class="page-epigraph-divider" aria-hidden="true"><span></span><svg viewBox="0 0 24 24" focusable="false"><path d="M12 2.75 14.15 7l4.6-1.75L17 9.85 21.25 12 17 14.15l1.75 4.6L14.15 17 12 21.25 9.85 17l-4.6 1.75L7 14.15 2.75 12 7 9.85l-1.75-4.6L9.85 7 12 2.75Z"/><circle cx="12" cy="12" r="2.2"/></svg><span></span></div></aside>`;
}
const DUAA_EPIGRAPHS={
  morning:{context:'Morning remembrance was the daily nourishment of the righteous.',quote:'"This is my breakfast. If I do not take my breakfast, I would not have strength to work that day."',citation:'Shaykh al-Islam Ibn Taymiyyah',detail:'As related by Ibn al-Qayyim and explained by Shaykh Salih al-Fawzan.',externalLink:{label:'Source: His Nourishment Was the Remembrance of Allah',url:'https://thewayofsalafiyyah.com/2015/06/14/his-nourishment-was-the-remembrance-of-allah-a-reminder-by-shaykh-fawzan/'}},
  evening:{quote:'"The example of the one who remembers his Lord and the one who does not remember his Lord is like the example of the living and the dead."',citation:['Prophet Muhammad ﷺ','Sahih al-Bukhari']},
  sleep:{quote:'"When you go to bed, perform ablution as you do for prayer, then lie down on your right side..."',citation:['Prophet Muhammad ﷺ','Sahih al-Bukhari & Sahih Muslim']},
  travel:{quote:'"Glorified is He Who has subjected this to us, and we could never have accomplished it by ourselves. And indeed, to our Lord we will surely return."',citation:'Qur’an 43:13–14'},
  weather:{quote:'"O Allah, I ask You for its goodness, the goodness within it, and the goodness with which it has been sent..."',citation:['Prophet Muhammad ﷺ','Sahih Muslim']},
  prayer:{quote:'"The closest that a servant comes to his Lord is while he is in prostration, so increase your supplications therein."',citation:['Prophet Muhammad ﷺ','Sahih Muslim']},
  food:{quote:'"O young boy! Mention Allah’s Name, eat with your right hand, and eat from what is nearest to you."',citation:['Prophet Muhammad ﷺ','Sahih al-Bukhari & Sahih Muslim']},
  clothing:{quote:'"Whoever puts on a garment and says: ‘Praise is to Allah Who clothed me with this and provided it for me without any strength or power on my part,’ his previous sins will be forgiven."',citation:['Prophet Muhammad ﷺ','Sunan Abi Dawud','Jami’ al-Tirmidhi']},
  anxiety:{quote:'"Unquestionably, by the remembrance of Allah hearts find rest."',citation:'Qur’an 13:28'},
  quranic:{quote:'"Our Lord says: Call upon Me; I will respond to you."',citation:'Qur’an 40:60'},
  collections:{quote:'"Your Lord says: ‘Call upon Me; I will respond to you.’"',citation:'Qur’an 40:60'},
};
function trackedCard(c){const count=completedCount(c.id),today=worshipToday(c.id);return `<article class="duaa-home-card"><div class="duaa-home-card-top"><span class="collection-type">Tracked daily</span><span class="home-status${today?' is-done':''}">${today?'Recorded today':'Not recorded today'}</span></div><div class="tracked-card-title"><img src="assets/duaa-${c.id}.svg" alt=""><h3>${esc(c.label)}</h3></div><p>${esc(c.intro)}</p><div class="mini-progress" aria-label="${count} of ${c.items.length} completed"><span style="width:${(count/c.items.length)*100}%"></span></div><div class="duaa-card-actions"><a class="button button-secondary" href="/duaa/${c.id}" data-route>Open Collection</a><button class="button ${today?'button-secondary is-done':'button-primary'}" type="button" data-toggle-worship="${c.id}" aria-pressed="${today}">${today?'✓ Done Today':'✓ Mark Done'}</button></div><div class="duaa-card-footer"><span>${count} of ${c.items.length} completed</span></div><div class="card-consistency"><div class="card-consistency-heading"><span>Weekly consistency ${infoTip('About weekly consistency','A day counts when you complete at least one duaa from this collection. Your collection progress is tracked separately.')}</span><a href="/duaa/history" data-route>View History</a></div>${week(c)}</div></article>`}
const collectionIndexImage=(id)=>id==='istikharah'?`assets/duaa-istikharah.svg`:`assets/collection-index-images-v3411/${id}.jpg`;
const homeCollectionImage=(id)=>id==='istikharah'?`assets/duaa-istikharah.svg`:`assets/duaa-home-card-images-v3411/${id}.jpg`;
function collectionArt(id){return `<div class="collection-art collection-art-${id}${id==='istikharah'?' is-fallback':''}" aria-hidden="true"><img src="${homeCollectionImage(id)}" alt=""></div>`}
function untrackedCard(c){return `<article class="collection-library-card">${collectionArt(c.id)}<div class="collection-library-copy"><span class="collection-type">Browse and read</span><h3>${esc(c.label)}</h3><p>${esc(c.intro)}</p><a href="/duaa/${c.id}" data-route>Open collection →</a></div></article>`}
function collectionListItem(c){
  const label=c.navLabel||c.label.replace(/ Duaas$/,'');
  const memorized=memorizedCount(c.id),total=c.items?.length||0,percent=total?Math.round((memorized/total)*100):0;
  return `<a class="collection-index-item" href="/duaa/${c.id}" data-route><span class="collection-index-image${c.id==='istikharah'?' is-fallback':''}"><img src="${collectionIndexImage(c.id)}" alt=""></span><span class="collection-index-copy"><strong>${esc(label)}</strong><span>${esc(c.intro)}</span></span><span class="collection-index-footer"><span class="collection-index-meta"><i class="collection-index-progress-ring" style="--progress:${percent}%" aria-hidden="true"></i><span>${memorized} of ${total} memorized</span></span><i class="ph ph-caret-right collection-index-caret" aria-hidden="true"></i></span></a>`
}

function duaaHome(){const tracked=duaaOrder.map(id=>duaaCollections[id]).filter(c=>c.tracked);const homeCollectionIds=new Set(['travel','weather','prayer','istikharah']);const other=duaaOrder.map(id=>duaaCollections[id]).filter(c=>!c.tracked&&homeCollectionIds.has(c.id));return `<section class="duaa-landing">${pageEpigraph(DUAA_EPIGRAPHS.collections)}<section class="home-section"><div class="section-heading"><div><p class="section-eyebrow">Daily companion</p><h3>Tracked collections</h3></div></div><div class="duaa-home-grid">${tracked.map(trackedCard).join('')}</div></section><section class="home-section"><div class="section-heading"><div><p class="section-eyebrow">More collections</p><h3>Browse by situation</h3></div><a class="section-link" href="/duaa/collections" data-route>View all collections →</a></div><div class="collection-library-grid is-compact">${other.map(untrackedCard).join('')}</div></section></section>`}
function week(c){return `<div class="week-row" aria-label="Weekly consistency">${weekStatus(c.id).map(d=>`<div class="week-day${d.active?' is-active':''}${d.today?' is-today':''}"><span>${d.label}</span><i aria-hidden="true"></i></div>`).join('')}</div>`}
function progressPanel(c){const count=completedCount(c.id),pct=Math.round(count/c.items.length*100),done=worshipToday(c.id);return `<aside class="progress-panel"><header class="progress-panel-header"><p class="panel-eyebrow">Today’s status</p></header><div class="progress-panel-body"><div class="today-status${done?' is-done':''}" role="status"><i class="ph ph-${done?'check-circle-fill':'circle'}" aria-hidden="true"></i><div><strong>${done?'Recorded today':'Not recorded'}</strong><span>${done?'At least one duaa counted today.':'One duaa is enough to count today.'}</span></div></div><button class="button button-primary worship-button${done?' is-recorded':''}" type="button" data-toggle-worship="${c.id}" aria-pressed="${done}">${done?'✓ Recorded for Today':'Record Today'}</button><div class="progress-summary" aria-label="Collection progress"><div><span>Collection progress</span><strong>${count} of ${c.items.length}</strong></div><div class="collection-progress"><span style="width:${pct}%"></span></div><small>${pct}% completed in the app</small></div><div class="weekly-block"><div class="weekly-heading"><span>Weekly consistency</span><a href="/duaa/history" data-route>View History</a></div>${week(c)}</div></div></aside>`}
function filterToken(value=''){return String(value).toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}
function collectionFilters(c){
  if(!c.filterable)return '';
  const speakers=[...new Map(c.items.map(item=>[item.speakerKey,item.speaker])).entries()];
  const purposes=[...new Set(c.items.flatMap(item=>item.purposes||[]))].sort((a,b)=>a.localeCompare(b)).map(x=>[filterToken(x),x]);
  const options=(group,values)=>values.map(([value,label])=>`<label class="collection-filter-option"><input type="checkbox" data-filter-group="${group}" data-filter-value="${esc(value)}"><span>${esc(label)}</span></label>`).join('');
  const selector=(group,label,buttonLabel,values)=>`<div class="collection-filter-selector"><span>${esc(label)}</span><button type="button" data-open-filter-dialog="${group}"><strong data-filter-summary="${group}">${esc(buttonLabel)}</strong><i class="ph ph-caret-down" aria-hidden="true"></i></button></div><dialog class="collection-filter-dialog" data-filter-dialog="${group}"><form method="dialog"><header><div><p class="section-eyebrow">Browse Collection</p><h3>${esc(label)}</h3></div><button class="dialog-close" value="close" aria-label="Close ${esc(label)} filter">×</button></header><div class="collection-filter-dialog-list">${options(group,values)}</div><footer><button class="button button-secondary" type="button" data-clear-filter-group="${group}">Clear selection</button><button class="button button-primary" value="close">Done</button></footer></form></dialog>`;
  return `<aside class="focus-about collection-filter-sidebar" data-collection-filters="${c.id}" aria-label="Browse collection filters"><h2>Browse Collection</h2><div class="collection-filter-sidebar-body">${selector('speaker','Prophet or Speaker','All prophets and speakers',speakers)}${selector('purpose','Purpose','All purposes',purposes)}<div class="collection-filter-active" data-active-filters hidden></div><p class="collection-filter-status" data-filter-status aria-live="polite">Showing all ${c.items.length} duaas</p><button class="collection-filter-clear" type="button" data-clear-collection-filters hidden>Clear all filters</button></div></aside>`;
}
function collectionList(c){
  const items=orderedItems(c.id);
  return `<div class="collection-list" data-collection-list="${c.id}">${items.map(d=>{
    const done=c.tracked&&isComplete(c.id,d.id),memorized=isMemorized(c.id,d.id),speaker=d.speaker||'',purposes=(d.purposes||[]).map(filterToken);
    return `<article class="duaa-index-row${done?' is-complete':''}${memorized?' is-memorized':''}" id="duaa-${esc(d.id)}" draggable="false" data-duaa-row="${d.id}" data-speaker="${esc(d.speakerKey||'')}" data-purposes="${esc(purposes.join(' '))}"><button class="reorder-handle" type="button" title="Drag to reorder ${esc(d.title)}" aria-label="Drag to reorder ${esc(d.title)}" data-drag-handle><svg viewBox="0 0 16 24" width="16" height="24" aria-hidden="true" focusable="false"><circle cx="5" cy="6" r="1.5"></circle><circle cx="11" cy="6" r="1.5"></circle><circle cx="5" cy="12" r="1.5"></circle><circle cx="11" cy="12" r="1.5"></circle><circle cx="5" cy="18" r="1.5"></circle><circle cx="11" cy="18" r="1.5"></circle></svg></button>${c.tracked?`<button class="row-state" type="button" data-toggle-complete="${c.id}:${d.id}" aria-pressed="${done}" aria-label="${done?'Remove completion from':'Mark complete'} ${esc(d.title)}"><i class="ph ph-check" aria-hidden="true"></i></button>`:'<span class="row-state is-empty" aria-hidden="true"></span>'}<div class="row-copy">${speaker?`<div class="quranic-row-meta"><span class="quranic-speaker-badge">${esc(speaker)}</span><span class="quranic-reference">${esc(d.surahName||'Qur’an')} ${esc(d.ayahRange||d.quranReference||'')}</span></div>`:''}<h3>${esc(d.title)}</h3><p>${esc(d.subtitle)}</p>${d.context?`<p class="quranic-context">${esc(d.context)}</p>`:''}${d.purposes?.length?`<div class="quranic-purpose-tags">${d.purposes.map(tag=>`<span>${esc(tag)}</span>`).join('')}</div>`:''}</div><button class="memorized-toggle${memorized?' is-memorized':''}" type="button" data-toggle-memorized="${c.id}:${d.id}" aria-pressed="${memorized}" aria-label="${memorized?'Mark as not memorized':'Mark as memorized'}: ${esc(d.title)}"><i class="ph ph-seal-check" aria-hidden="true"></i><span>${memorized?'Memorized':'Mark memorized'}</span></button><a class="read-link" href="/duaa/${c.id}/read/${d.id}" data-route>Read <span aria-hidden="true">→</span></a></article>`
  }).join('')}</div>`
}

function collectionPage(c){
  const epigraph=DUAA_EPIGRAPHS[c.id]||{quote:`“${c.quote}”`,citation:c.quoteSource};
  const collectionBody=c.items.length
    ?`${collectionList(c)}`
    :`<div class="collection-empty-state"><i class="ph ph-book-open-text" aria-hidden="true"></i><h4>Collection page ready</h4><p>The page and banner are in place. Verified duaa entries can be added in the dedicated content pass.</p><a href="/duaa/collections" data-route>Return to Collections</a></div>`;
  const filters=collectionFilters(c);
  return `<section class="collection-page">${pageEpigraph(epigraph)}<div class="collection-layout${c.tracked?'':' is-untracked'}${filters?' has-filter-sidebar':''}">${c.tracked?progressPanel(c):filters}<section class="collection-main"><div class="collection-heading"><div><p class="section-eyebrow">${esc(c.navLabel||c.label)}</p><h3>${c.items.length} ${c.items.length===1?'duaa':'duaas'}</h3></div>${c.items.length?`<div class="collection-tools">${infoTip('How to reorder duaas','Drag the six-dot handle to arrange these duaas in the order you prefer.')}</div>`:''}</div>${collectionBody}</section></div></section>`;
}

function duaaMemorizationPage(){
  const groups=duaaOrder.map(id=>duaaCollections[id]).filter(Boolean);
  const total=totalUniqueDuaaCount(),memorized=totalMemorizedCount(),started=groups.filter(c=>memorizedCount(c.id)>0).length;
  const sections=groups.map((c,collectionIndex)=>{
    const count=memorizedCount(c.id),pct=c.items.length?Math.round(count/c.items.length*100):0;
    return `<section class="memorization-collection" style="--collection-index:${collectionIndex}"><header><div><p class="section-eyebrow">${esc(c.navLabel||c.label)}</p><h3>${count} of ${c.items.length} memorized</h3></div><span>${pct}%</span></header><div class="memorization-progress"><span style="width:${pct}%"></span></div><div class="duaa-badge-grid">${orderedItems(c.id).map((item,index)=>{const learned=isMemorized(c.id,item.id);return `<article class="duaa-memory-badge${learned?' is-memorized':''}"><a href="/duaa/${c.id}/read/${item.id}" data-route aria-label="Read ${esc(item.title)}"><span class="badge-number">${index+1}</span><i class="ph ph-seal-check" aria-hidden="true"></i><strong>${esc(item.title)}</strong></a><button type="button" data-toggle-memorized="${c.id}:${item.id}" aria-pressed="${learned}">${learned?'Memorized':'Mark memorized'}</button></article>`}).join('')}</div></section>`
  }).join('');
  return `<section class="duaa-memorization-page"><header class="memorization-intro"><p class="page-kicker">Duaa memorization</p><h2>My Duaa Memorization</h2><p>Watch your collection gradually fill with color as each supplication becomes part of what you know.</p></header><div class="memorization-summary"><article><span>Unique duaas</span><strong>${total}</strong></article><article><span>Memorized</span><strong>${memorized}</strong></article><article><span>Still learning</span><strong>${total-memorized}</strong></article><article><span>Collections started</span><strong>${started}</strong></article></div>${sections}</section>`
}

function collectionsPage(){const collections=duaaOrder.map(id=>duaaCollections[id]).filter(Boolean).sort((a,b)=>(a.navLabel||a.label).localeCompare(b.navLabel||b.label));return `<section class="collections-page">${pageEpigraph(DUAA_EPIGRAPHS.collections)}<nav class="collection-index" aria-label="Duaa collections">${collections.map(collectionListItem).join('')}</nav></section>`}
const studyGroups=[['Audio','audio','headphones','Lectures and explanations'],['Videos','video','video-camera','Selected video reminders'],['Articles','article','file-text','Authentic articles and benefits'],['Books','book','book-open','Recommended reading'],['Tweets / Posts','tweet','chat-circle-dots','Short reminders and threads'],['Telegram','telegram','paper-plane-tilt','Trusted channel posts']];
function itemResources(item,type){const linked=resourcesByIds(item.resourceIds||[]);const fallback=Array.isArray(item.resources)?item.resources:[];return (linked.length?linked:fallback).filter(resource=>String(resource.type||'').toLowerCase()===type)}
function sourceLink(source,label='View source'){
  if(!source) return '';
  if(source.url) return `<a class="focus-source-link" href="${esc(source.url)}" target="_blank" rel="noopener noreferrer"><span>${esc(label)}</span><i class="ph ph-arrow-square-out" aria-hidden="true"></i></a>`;
  return `<span class="focus-source-link is-pending"><span>${esc(source.citation)}</span><small>Link pending</small></span>`;
}
function focusStudyResources(item){
  const groups=studyGroups.map(([label,type,icon])=>({label,type,icon,resources:itemResources(item,type)})).filter(group=>group.resources.length);
  const total=groups.reduce((sum,group)=>sum+group.resources.length,0);
  return `<details class="focus-study-resources"><summary><span class="focus-study-summary-label"><span class="focus-study-summary-icon"><i class="ph ph-books" aria-hidden="true"></i></span><span>Study Resources (${total})</span></span><i class="ph ph-caret-down focus-study-caret" aria-hidden="true"></i></summary><div class="focus-resource-groups">${groups.length?groups.map(group=>`<section class="focus-resource-group"><h4><i class="ph ph-${group.icon}" aria-hidden="true"></i>${esc(group.label)} <span>(${group.resources.length})</span></h4><div>${group.resources.map(resource=>`<a href="${esc(resource.url||resource.link||'#')}" target="_blank" rel="noopener noreferrer"><span><strong>${esc(resourceTitle(resource))}</strong>${resourceMeta(resource)?`<small>${esc(resourceMeta(resource))}</small>`:''}</span><i class="ph ph-arrow-square-out" aria-hidden="true"></i></a>`).join('')}</div></section>`).join(''):`<p class="focus-resources-empty">No study resources have been added yet.</p>`}</div></details>`;
}
function focusAboutPanel(item){
  const sources=sourcesByIds(item.sourceIds||[]),virtueSources=sourcesByIds(item.virtue?.sourceIds||[]);
  return `<aside class="focus-about" aria-label="About this duaa"><h2>About This Duaa</h2>${item.speaker?`<section class="focus-about-section quranic-focus-attribution"><span class="focus-about-icon"><i class="ph ph-user-focus" aria-hidden="true"></i></span><div><h3>${esc(item.speaker)}</h3><p>${esc(item.surahName||'Qur’an')} ${esc(item.ayahRange||item.quranReference||'')}</p>${item.context?`<small>${esc(item.context)}</small>`:''}</div></section>`:''}<section class="focus-about-section focus-evidence"><span class="focus-about-icon"><i class="ph ph-book-open-text" aria-hidden="true"></i></span><div><h3>Evidence</h3><div class="focus-source-list">${sources.length?sources.map(source=>sourceLink(source,source.citation)).join(''):item.sourceDetails?.sourceReference?sourceLink({url:item.sourceDetails.sourceReference,citation:item.source},item.source):`<span>${esc(item.source||'Source pending')}</span>`}</div>${item.sourceDetails?.grade?`<p class="focus-source-grade">${esc(item.sourceDetails.grade)}</p>`:''}</div></section>${item.virtue?.text?`<section class="focus-about-section focus-virtue"><span class="focus-about-icon"><i class="ph ph-sparkle" aria-hidden="true"></i></span><div><h3>Virtue / Benefit</h3><p>${esc(item.virtue.text)}</p>${virtueSources.length?`<div class="focus-source-list is-virtue">${virtueSources.map(source=>sourceLink(source,source.citation)).join('')}</div>`:''}</div></section>`:''}${focusStudyResources(item)}</aside>`;
}
function readingSettings(prefs){return `<dialog class="reading-settings" data-reading-dialog><form method="dialog"><header><div><p class="section-eyebrow">Reading display</p><h2>Reading Preferences</h2></div><button class="dialog-close" value="close" aria-label="Close reading preferences">×</button></header><label class="range-field" for="arabic-size"><span>Arabic text size</span><input id="arabic-size" type="range" min="1.7" max="3.4" step="0.1" value="${prefs.arabicSize}" data-reading-size><output data-size-output>${prefs.arabicSize.toFixed(1)}rem</output></label><fieldset><legend>Display</legend><label class="check-row"><input type="checkbox" data-reading-transliteration ${prefs.showTransliteration?'checked':''}><span>Transliteration</span></label><label class="check-row"><input type="checkbox" data-reading-english ${prefs.showEnglish?'checked':''}><span>English translation</span></label></fieldset><button class="button button-primary" value="close">Done</button></form></dialog>`}
function learningSegments(item){
  return Array.isArray(item.segments)&&item.segments.length?item.segments:(item.focusPhrases||[]).map(segment=>({arabic:segment.arabic,english:segment.translation,transliteration:segment.transliteration}));
}
function hasSegmentedLearningData(item){
  const explicitPhrases=Array.isArray(item.focusPhrases)&&item.focusPhrases.length>0;
  const segments=Array.isArray(item.segments)?item.segments:[];
  if(explicitPhrases) return true;
  if(segments.length>1) return true;
  // A single generated segment that only repeats the complete Arabic/English text
  // is a Read Mode fallback, not phrase-by-phrase Learn content.
  return segments.length===1&&Boolean(String(segments[0].transliteration||'').trim());
}
function readView(item,prefs){
  const english=item.english||item.translation||learningSegments(item).map(segment=>segment.english).filter(Boolean).join(' ');
  const arabic=item.arabic||learningSegments(item).map(segment=>segment.arabic).filter(Boolean).join(' ');
  return `<section class="focus-read-view${prefs.showEnglish?'':' is-arabic-only'}" aria-label="Read the complete duaa">${prefs.showEnglish?`<article class="focus-read-column focus-read-english"><span class="focus-read-label">English</span><p>${esc(english)}</p></article>`:''}<article class="focus-read-column focus-read-arabic" lang="ar" dir="rtl"><span class="focus-read-label">Arabic</span><p>${esc(arabic)}</p></article></section>`;
}
function learnView(item,prefs){
  if(!hasSegmentedLearningData(item)) return learnUnavailableView();
  const segments=learningSegments(item);
  const layoutClass=!prefs.showTransliteration&&!prefs.showEnglish?' is-arabic-only':(!prefs.showTransliteration||!prefs.showEnglish?' is-two-column':'');
  return `<section class="duaa-learning focus-learning${layoutClass}" aria-label="Learn the duaa phrase by phrase"><div class="learning-grid learning-grid-heading" aria-hidden="true">${prefs.showTransliteration?'<span>Transliteration</span>':''}${prefs.showEnglish?'<span>English</span>':''}<span>Arabic</span></div>${segments.map((segment,index)=>`<article class="learning-segment"><span class="segment-number">${index+1}</span><div class="learning-grid">${prefs.showTransliteration?`<p class="segment-transliteration"><span class="mobile-segment-label">Transliteration</span><span class="segment-text segment-text-transliteration">${segment.transliteration?esc(segment.transliteration):'<span class="segment-missing">Transliteration not yet added</span>'}</span></p>`:''}${prefs.showEnglish?`<p class="segment-english"><span class="mobile-segment-label">English</span><span class="segment-text segment-text-english">${esc(segment.english)}</span></p>`:''}<p class="segment-arabic" lang="ar" dir="rtl"><span class="mobile-segment-label">Arabic</span><span class="segment-text segment-text-arabic" lang="ar" dir="rtl">${esc(segment.arabic)}</span></p></div></article>`).join('')}</section>`;
}
function learnUnavailableView(){
  return `<section class="focus-learn-unavailable" aria-labelledby="learn-unavailable-title"><i class="ph ph-student" aria-hidden="true"></i><h2 id="learn-unavailable-title">Learn Mode</h2><p>Line-by-line learning isn't available for this duaa yet.</p><p>This supplication is currently available in Read mode.</p><p>Phrase-by-phrase learning with aligned Arabic, transliteration, and English will be added in a future update.</p><button class="button button-primary" type="button" data-reading-mode="read"><i class="ph ph-caret-left" aria-hidden="true"></i><span>Return to Read</span></button></section>`;
}
function readerModeTabs(mode){
  return `<div class="focus-mode-tabs" role="tablist" aria-label="Reading view"><button type="button" role="tab" aria-selected="${mode==='read'}" class="${mode==='read'?'is-active':''}" data-reading-mode="read"><i class="ph ph-book-open" aria-hidden="true"></i><span>Read</span></button><button type="button" role="tab" aria-selected="${mode==='learn'}" class="${mode==='learn'?'is-active':''}" data-reading-mode="learn"><i class="ph ph-student" aria-hidden="true"></i><span>Learn</span></button></div>`;
}
function activeReadingItems(c,currentItemId){
  const allItems=orderedItems(c.id);
  if(c.id!=='quranic') return allItems;
  try {
    const savedIds=JSON.parse(sessionStorage.getItem(`ummiby.collectionReadingSequence.${c.id}`)||'[]');
    if(!Array.isArray(savedIds)||!savedIds.length) return allItems;
    const byId=new Map(allItems.map(item=>[item.id,item]));
    const filtered=savedIds.map(id=>byId.get(id)).filter(Boolean);
    return filtered.some(item=>item.id===currentItemId)?filtered:allItems;
  } catch { return allItems; }
}
function readerPage(c,item,items=activeReadingItems(c,item.id)){
  const i=Math.max(0,items.findIndex(x=>x.id===item.id)),savedPrefs=readingPreferences(),segments=learningSegments(item),hasTransliteration=segments.some(segment=>Boolean(segment.transliteration)),mode=savedPrefs.mode,prefs={...savedPrefs,showTransliteration:hasTransliteration&&savedPrefs.showTransliteration},done=isComplete(c.id,item.id),progress=((i+1)/items.length)*100;
  return `<section class="reader-page focus-reader" style="--reader-arabic-size:${prefs.arabicSize}rem;--focus-progress:${progress}%"><header class="reader-top focus-reader-top"><a class="reader-exit" href="/duaa/${c.id}" data-route data-exit-reader><i class="ph ph-caret-left" aria-hidden="true"></i><span>Exit Reading Mode</span></a><div class="reader-position"><span>${esc(c.label)}</span><strong>${i+1} of ${items.length}</strong><div class="focus-progress" aria-label="Duaa ${i+1} of ${items.length}"><span></span></div></div><button class="reader-settings-button" type="button" data-reading-settings aria-label="Open reading preferences"><i class="ph ph-gear-six" aria-hidden="true"></i></button></header><div class="focus-workspace">${focusAboutPanel(item)}<main class="focus-main"><header class="focus-duaa-heading"><h1>${esc(item.title)}</h1>${(item.repeat||item.count)?`<div class="focus-repeat"><span></span><p>Repeat ${esc(item.repeat||item.count)}</p><span></span></div>`:''}</header>${readerModeTabs(mode)}${mode==='learn'?learnView(item,prefs):readView(item,prefs)}</main></div><nav class="reader-controls focus-reader-controls" aria-label="Reading controls"><div class="focus-control-group">${i>0?`<a href="/duaa/${c.id}/read/${items[i-1].id}" data-route><i class="ph ph-caret-left" aria-hidden="true"></i><span>Previous</span></a>`:'<span class="focus-control-spacer"></span>'}${c.tracked?`<button class="focus-complete-toggle${done?' is-complete':''}" type="button" data-toggle-complete="${c.id}:${item.id}">${done?'<i class="ph ph-check-circle" aria-hidden="true"></i><span>Completed</span>':'<i class="ph ph-check-circle" aria-hidden="true"></i><span>Mark Complete</span>'}</button>`:'<span class="focus-control-spacer"></span>'}${i<items.length-1?`<a href="/duaa/${c.id}/read/${items[i+1].id}" data-route><span>Next</span><i class="ph ph-caret-right" aria-hidden="true"></i></a>`:`<a class="focus-end-control" href="/duaa/${c.id}" data-route data-exit-reader aria-label="End of collection. Exit Reading Mode"><span><small>End of collection</small><strong>Exit Reading Mode</strong></span><i class="ph ph-list-bullets" aria-hidden="true"></i></a>`}</div></nav>${readingSettings(prefs)}</section>`;
}
function resourceTitle(resource){return resource.title||resource.name||resource.label||'Study resource'}
function resourceMeta(resource){return resource.author||resource.speaker||resource.source||''}
function studyCategoryPage(c,item,type){const group=studyGroups.find(x=>x[1]===type)||studyGroups[0],resources=itemResources(item,type);return `<section class="study-detail-page"><header class="reader-top"><a href="/duaa/${c.id}/read/${item.id}" data-route>← Back to Study Library</a><div class="reader-position"><span>${esc(c.label)}</span><strong>${esc(item.title)}</strong></div></header><main class="study-detail-content"><div class="study-detail-heading"><span class="study-heading-icon"><i class="ph ph-${group[2]}" aria-hidden="true"></i></span><div><p class="section-eyebrow">Study Library</p><h2>${group[0]} Resources</h2><p>${group[3]} related to this duaa.</p></div><span class="resource-count">${resources.length} ${resources.length===1?'resource':'resources'}</span></div>${resources.length?`<div class="resource-list">${resources.map(resource=>`<a class="resource-row" href="${esc(resource.url||resource.link||'#')}" target="_blank" rel="noopener noreferrer"><span><strong>${esc(resourceTitle(resource))}</strong><small>${esc(resourceMeta(resource))}</small></span>${resource.duration?`<em>${esc(resource.duration)}</em>`:''}<i class="ph ph-arrow-square-out" aria-hidden="true"></i></a>`).join('')}</div>`:`<div class="study-empty"><i class="ph ph-books" aria-hidden="true"></i><h3>No ${group[0].toLowerCase()} resources yet</h3><p>This category is ready for trusted resources when they are added.</p></div>`}<p class="external-note"><i class="ph ph-info" aria-hidden="true"></i> Resources open in a new tab. Ummiby Companion does not host or control external content.</p></main></section>`}
function historyDateKey(date){const y=date.getFullYear(),m=String(date.getMonth()+1).padStart(2,'0'),d=String(date.getDate()).padStart(2,'0');return `${y}-${m}-${d}`}
const DUAA_HISTORY_START_YEAR=2026;
function historyYearOptions(collectionId,selectedYear){
  const currentYear=new Date().getFullYear();
  const recordYears=Object.keys(duaaHistoryRecords(collectionId))
    .map(key=>Number(key.slice(0,4)))
    .filter(year=>Number.isInteger(year)&&year<DUAA_HISTORY_START_YEAR);
  const earliest=Math.min(DUAA_HISTORY_START_YEAR,...recordYears);
  const latest=Math.max(currentYear+1,selectedYear);
  return Array.from({length:latest-earliest+1},(_,index)=>latest-index)
    .map(year=>`<option value="${year}"${year===selectedYear?' selected':''}>${year}</option>`)
    .join('');
}
function historyCalendar(collectionId,view){
  const records=duaaHistoryRecords(collectionId),today=historyDateKey(new Date());
  const month=new Date(view.year,view.month,1),firstDay=month.getDay(),daysInMonth=new Date(view.year,view.month+1,0).getDate();
  const previousMonth=new Date(view.year,view.month,0).getDate(),cells=[];
  for(let i=firstDay-1;i>=0;i--)cells.push({day:previousMonth-i,outside:true,date:new Date(view.year,view.month-1,previousMonth-i)});
  for(let day=1;day<=daysInMonth;day++)cells.push({day,outside:false,date:new Date(view.year,view.month,day)});
  let next=1;while(cells.length%7)cells.push({day:next++,outside:true,date:new Date(view.year,view.month+1,next-1)});
  return `<section class="history-calendar-card"><header class="history-calendar-header"><button class="history-month-button" type="button" data-history-month="-1" aria-label="Previous month"><i class="ph ph-caret-left"></i></button><div class="history-calendar-heading"><p class="section-eyebrow">Monthly record</p><h3>${month.toLocaleDateString('en-US',{month:'long'})}</h3><label class="history-year-jump"><span>Jump to year</span><select data-history-year aria-label="Jump to year">${historyYearOptions(collectionId,view.year)}</select></label></div><button class="history-month-button" type="button" data-history-month="1" aria-label="Next month"><i class="ph ph-caret-right"></i></button></header><p class="history-calendar-help"><i class="ph ph-pencil-simple" aria-hidden="true"></i> Select today or a past date to record duaas completed outside Ummiby or correct your history.</p><div class="history-weekdays" aria-hidden="true">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(day=>`<span>${day}</span>`).join('')}</div><div class="history-calendar-grid">${cells.map(cell=>{const key=historyDateKey(cell.date),record=records[key],future=key>today;return `<button type="button" class="history-day${cell.outside?' is-outside':''}${record?.active?' is-active':''}${record?.complete?' is-complete':''}${key===today?' is-today':''}${future?' is-future':''}" data-edit-duaa-day="${key}" ${future?'disabled':''} aria-label="${key}: ${record?.complete?'Collection completed':record?.active?'Active day':future?'Future date':'No activity'}. ${future?'Not editable':'Select to edit daily activity'}"><span>${cell.day}</span>${record?.active?`<i aria-hidden="true"></i>`:''}</button>`}).join('')}</div><footer class="history-legend"><span><i class="is-active"></i>Active day</span><span><i class="is-complete"></i>Collection completed</span><span><i class="is-today"></i>Today</span></footer></section>`;
}
function monthHistoryInsights(collectionId,year,month){
  const records=duaaHistoryRecords(collectionId),today=new Date(),monthStart=new Date(year,month,1),monthEnd=new Date(year,month+1,0),isCurrentMonth=year===today.getFullYear()&&month===today.getMonth();
  const throughDate=isCurrentMonth?today:monthEnd;
  const isFutureMonth=monthStart>new Date(today.getFullYear(),today.getMonth(),today.getDate());
  const eligibleDays=isFutureMonth?0:Math.max(0,Math.min(monthEnd.getDate(),throughDate.getDate()));
  const monthRecords=Object.values(records).filter(record=>{const date=new Date(`${record.date}T12:00:00`);return date.getFullYear()===year&&date.getMonth()===month&&date<=throughDate;});
  const activeDates=monthRecords.filter(record=>record.active).map(record=>record.date).sort();
  const completedDays=monthRecords.filter(record=>record.complete).length;
  let longest=0,run=0,previous=null;
  activeDates.forEach(key=>{const date=new Date(`${key}T12:00:00`),consecutive=previous&&Math.round((date-previous)/86400000)===1;run=consecutive?run+1:1;longest=Math.max(longest,run);previous=date;});
  const weekCounts=[0,0,0,0,0,0];
  activeDates.forEach(key=>{const date=new Date(`${key}T12:00:00`),week=Math.min(5,Math.floor((date.getDate()+new Date(year,month,1).getDay()-1)/7));weekCounts[week]++;});
  const bestWeekCount=Math.max(0,...weekCounts),bestWeekIndex=bestWeekCount?weekCounts.indexOf(bestWeekCount):-1;
  const weekdayCounts=[0,0,0,0,0,0,0];
  activeDates.forEach(key=>weekdayCounts[new Date(`${key}T12:00:00`).getDay()]++);
  const bestWeekdayCount=Math.max(0,...weekdayCounts),bestWeekdayIndex=bestWeekdayCount?weekdayCounts.indexOf(bestWeekdayCount):-1;
  const weekdayNames=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
  const monthLabel=monthStart.toLocaleDateString('en-US',{month:'long'});
  let encouragement='Every duaa counts. Your monthly pattern will grow as you continue.';
  if(isFutureMonth) encouragement=`${monthLabel} has not begun yet. This space will fill as your remembrance history grows.`;
  else if(!activeDates.length) encouragement=`No activity has been recorded for ${monthLabel} yet. Even one duaa can begin the pattern.`;
  else if(longest>=7) encouragement=`Alḥamdulillāh—you built a ${longest}-day active streak this month.`;
  else if(activeDates.length>=Math.ceil(eligibleDays*.7)) encouragement='A strong month of steady remembrance is taking shape.';
  else if(activeDates.length>=3) encouragement=`You have returned on ${activeDates.length} days this month. Keep building gently.`;
  return {activeDays:activeDates.length,eligibleDays,completedDays,longest,bestWeekCount,bestWeekIndex,bestWeekdayCount,bestWeekdayIndex,weekdayNames,encouragement,isFutureMonth};
}
function historyInsights(collectionId,view){
  const insight=monthHistoryInsights(collectionId,view.year,view.month),monthLabel=new Date(view.year,view.month,1).toLocaleDateString('en-US',{month:'long',year:'numeric'});
  const rows=insight.isFutureMonth?[]:[
    ['calendar-check','Active this month',`${insight.activeDays} of ${insight.eligibleDays} days`],
    ['fire','Longest monthly streak',`${insight.longest} ${insight.longest===1?'day':'days'}`],
    ['calendar-dots','Most consistent week',insight.bestWeekCount?`Week ${insight.bestWeekIndex+1} · ${insight.bestWeekCount} active ${insight.bestWeekCount===1?'day':'days'}`:'Not enough activity yet'],
    ['calendar-blank','Most consistent weekday',insight.bestWeekdayCount?`${insight.weekdayNames[insight.bestWeekdayIndex]} · ${insight.bestWeekdayCount} ${insight.bestWeekdayCount===1?'time':'times'}`:'Not enough activity yet']
  ];
  return `<section class="history-insights-card"><p class="section-eyebrow">Monthly insights</p><h3>${monthLabel}</h3>${rows.length?`<div class="history-insight-list">${rows.map(([icon,label,value])=>`<div><i class="ph ph-${icon}" aria-hidden="true"></i><span><small>${label}</small><strong>${value}</strong></span></div>`).join('')}</div>`:''}<div class="history-encouragement"><i class="ph ph-sparkle" aria-hidden="true"></i><p>${insight.encouragement}</p></div></section>`;
}
function history(view={}){const collectionId=['morning','evening','sleep'].includes(view.collectionId)?view.collectionId:'morning',now=new Date(),normalized={collectionId,year:Number.isInteger(view.year)?view.year:now.getFullYear(),month:Number.isInteger(view.month)?view.month:now.getMonth()},summary=duaaHistorySummary(collectionId);return `<section class="duaa-history-page"><header class="history-page-intro"><p class="section-eyebrow">Every duaa counts</p><h2>Your remembrance history</h2><p>See the quiet pattern of your daily remembrance. Active-day streaks honor consistency, even when a collection was not fully completed.</p></header><nav class="history-tabs" aria-label="Duaa history collections">${['morning','evening','sleep'].map(id=>`<button type="button" class="history-tab${id===collectionId?' is-active':''}" data-history-collection="${id}" aria-pressed="${id===collectionId}"><img src="assets/duaa-${id}.svg" alt=""><span>${esc(duaaCollections[id].navLabel||duaaCollections[id].label.replace(/ Duaas$/,''))}</span></button>`).join('')}</nav><section class="history-summary-grid"><article><i class="ph ph-calendar-check"></i><span>Active Days</span><strong>${summary.activeDays}</strong></article><article><i class="ph ph-seal-check"></i><span>Completed Days</span><strong>${summary.completedDays}</strong></article><article><i class="ph ph-chart-donut"></i><span>Completion Rate</span><strong>${summary.completionRate===null?'—':`${summary.completionRate}%`}</strong></article><article><i class="ph ph-fire"></i><span>Current Streak</span><strong>${summary.currentStreak}</strong></article><article><i class="ph ph-trophy"></i><span>Longest Streak</span><strong>${summary.longestStreak}</strong></article></section><div class="history-workspace">${historyCalendar(collectionId,normalized)}${historyInsights(collectionId,normalized)}</div><dialog class="daily-activity-dialog" data-duaa-day-dialog><form method="dialog" class="daily-activity-card"><header><div><p class="section-eyebrow">Record Duaa Activity</p><h3 data-duaa-day-title>Selected date</h3><p>Record collections completed outside Ummiby or correct this day’s history.</p></div><button type="button" class="dialog-close" data-close-duaa-day aria-label="Close"><i class="ph ph-x"></i></button></header><div class="daily-activity-options">${['morning','evening','sleep'].map(id=>`<label><input type="checkbox" data-duaa-day-activity="${id}"><img src="assets/duaa-${id}.svg" alt=""><span><strong>${esc(duaaCollections[id].navLabel||duaaCollections[id].label.replace(/ Duaas$/,''))}</strong><small>Completed on this date</small></span><i class="ph ph-check-circle" aria-hidden="true"></i></label>`).join('')}</div><p class="daily-activity-note"><i class="ph ph-info"></i> Changes update the calendar, Today’s Status, weekly consistency, and monthly insights.</p><footer><button type="button" class="button button-secondary" data-close-duaa-day>Cancel</button><button type="button" class="button button-primary" data-save-duaa-day>Save Changes</button></footer></form></dialog></section>`}
function settings(){return `<section><header class="editorial-header"><p class="page-kicker">Duaa preferences</p><h2>Settings</h2><p>Collection-specific reading and Arabic display controls will live here as the module expands.</p></header><article class="settings-placeholder"><h3>Reading display</h3><p>The new reader uses spacious Arabic, transliteration, meaning, and source sections. Existing account-wide preferences remain unchanged.</p></article></section>`}
function duaaContent(path,historyView){const p=routeParts(path);if(path==='/duaa')return duaaHome();if(path==='/duaa/collections')return collectionsPage();if(path==='/duaa/memorization')return duaaMemorizationPage();if(path==='/duaa/history')return history(historyView);const c=duaaCollections[p[1]];if(!c)return `<section class="empty-state"><h2>Collection not found</h2><a href="/duaa" data-route>Return to Duaa Home</a></section>`;if(p[2]==='read'){const allItems=orderedItems(c.id);const item=allItems.find(x=>x.id===p[3])||allItems[0];if(p[4]==='study'&&p[5])return studyCategoryPage(c,item,p[5]);return readerPage(c,item,activeReadingItems(c,item.id))}return collectionPage(c)}
function visionIcon(name){return `<span class="vision-icon"><i class="ph ph-${name}" aria-hidden="true"></i></span>`}
function progressBar(value){return `<div class="vision-progress"><span style="width:${value}%"></span></div>`}
function quranDateKey(date=new Date()){const year=date.getFullYear(),month=String(date.getMonth()+1).padStart(2,'0'),day=String(date.getDate()).padStart(2,'0');return `${year}-${month}-${day}`}
function quranReadingDays(){try{return JSON.parse(localStorage.getItem('ummiby.quran.readingDays')||'{}')}catch{return {}}}
function quranReadToday(){return Boolean(quranReadingDays()[quranDateKey()])}
function quranWeek(){const today=new Date(),sunday=new Date(today);sunday.setDate(today.getDate()-today.getDay());const records=quranReadingDays();return Array.from({length:7},(_,i)=>{const date=new Date(sunday);date.setDate(sunday.getDate()+i);return {label:['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][i],done:Boolean(records[quranDateKey(date)]),today:i===today.getDay()}})}
function quranSurahLabel(number,name){return `Surah ${Number(number)} • ${name}`}
function quranSavedPlaceLabel(unit,ayah){return `${quranSurahLabel(unit.surahNumber,unit.surahName)}, Ayah ${Number(ayah)}`}
function readingUnitIncludes(unit){
  if(Array.isArray(unit.includes)&&unit.includes.length)return unit.includes;
  return [`The passage from ${quranSurahLabel(unit.surahNumber,unit.surahName)} assigned to this reading unit.`];
}
function quranReadingTooltip(){return `<span class="quran-info-tip" tabindex="0" aria-label="About recording outside reading"><i class="ph ph-info" aria-hidden="true"></i><span class="quran-info-popover">Use this only for Qur’an reading completed outside Ummiby Companion, such as a printed mushaf, the masjid, or another app. Reading inside the app is recorded automatically.</span></span>`}
function quranJourneyDefaults(){const progress=readingJourneyProgress(),unit=getReadingUnit(progress.current)||getReadingUnit(1);return {
  'reading-unit':{id:'reading-unit',name:'Reading Unit Journey',position:`Reading Unit ${unit.order} · ${quranSurahLabel(unit.surahNumber,unit.surahName)}, Ayat ${unit.startAyah}–${unit.endAyah}`,progress:progress.percent,current:unit.order,total:QURAN_CANONICAL_STATUS.readingUnits,unitLabel:'units',continueRoute:`/quran/reading-unit/${unit.order}`,indexRoute:'/quran/reading-units'},
  'classic':{id:'classic',name:'Classic Journey',position:'Surah 2 • Al-Baqarah, Ayah 253',progress:18,current:18,total:114,unitLabel:'surahs',continueRoute:'/quran/classic/al-baqarah',indexRoute:'/quran/surahs'}
};}
function journeyState(){
  let stored={};
  try{stored=JSON.parse(localStorage.getItem('ummiby.quran.journeys')||'{}')||{}}catch{}
  let legacy=null;
  try{legacy=JSON.parse(localStorage.getItem('ummiby.quran.activeJourney')||'null')}catch{}
  const journeys=Object.fromEntries(Object.entries(quranJourneyDefaults()).map(([id,defaults])=>[id,{...defaults,...(stored.journeys?.[id]||{}),...(legacy?.id===id?legacy:{})}]));
  const activeId=stored.activeId&&journeys[stored.activeId]?stored.activeId:(legacy?.id&&journeys[legacy.id]?legacy.id:'reading-unit');
  return {activeId,journeys};
}
export function saveActiveJourney(id){
  const state=journeyState();
  if(!state.journeys[id])return false;
  state.activeId=id;
  localStorage.setItem('ummiby.quran.journeys',JSON.stringify(state));
  localStorage.setItem('ummiby.quran.activeJourney',JSON.stringify(state.journeys[id]));
  return true;
}
function activeJourney(){const state=journeyState();return state.journeys[state.activeId]}

