function kahfFridayKey(date=new Date()){const friday=new Date(date);const day=friday.getDay();const delta=day===5?0:(day===6?-1:-(day+2));friday.setDate(friday.getDate()+delta);return quranDateKey(friday)}
function kahfRecords(){try{return JSON.parse(localStorage.getItem('ummiby.quran.kahfFriday.records')||'{}')}catch{return {}}}
function kahfActive(){try{const value=JSON.parse(localStorage.getItem('ummiby.quran.kahfFriday.active')||'{}');return value.fridayDate===kahfFridayKey()?value:{fridayDate:kahfFridayKey(),completedSections:[],currentSection:1,savedAyah:0}}catch{return {fridayDate:kahfFridayKey(),completedSections:[],currentSection:1,savedAyah:0}}}
function kahfStatusFor(key){return kahfRecords()[key]?.status||'none'}
function kahfHijriDate(date=new Date()){try{return new Intl.DateTimeFormat('en-US-u-ca-islamic',{weekday:'long',month:'long',day:'numeric',year:'numeric'}).format(date)}catch{return ''}}
function kahfCalendar(){const offset=Number(localStorage.getItem('ummiby.quran.kahfFriday.calendarOffset')||0),view=new Date();view.setDate(1);view.setMonth(view.getMonth()+offset);const now=new Date(),todayKey=quranDateKey(now),currentFriday=kahfFridayKey(now),year=view.getFullYear(),month=view.getMonth(),first=new Date(year,month,1),last=new Date(year,month+1,0),records=kahfRecords();const cells=[];for(let i=0;i<first.getDay();i++)cells.push('<span class="kahf-calendar-empty"></span>');for(let day=1;day<=last.getDate();day++){const date=new Date(year,month,day),key=quranDateKey(date),isFriday=date.getDay()===5,isToday=key===todayKey,isCurrentFriday=key===currentFriday,status=records[key]?.status||'none',future=date>now;const classes=['kahf-calendar-day'];if(isFriday)classes.push('is-friday');if(isToday)classes.push('is-today');if(isCurrentFriday)classes.push('is-current-friday');if(isFriday&&status==='complete')classes.push('is-complete');else if(isFriday&&status==='partial')classes.push('is-partial');else if(isFriday&&future)classes.push('is-upcoming');else if(future)classes.push('is-future');const marker=isFriday&&(status==='complete'||status==='partial'||future)?`<i class="kahf-calendar-marker ${status==='complete'?'is-complete':status==='partial'?'is-partial':'is-upcoming'}" aria-hidden="true"></i>`:'';cells.push(`<span class="${classes.join(' ')}" title="${isFriday?(status==='complete'?'Completed Friday':status==='partial'?'Partially completed Friday':future?'Upcoming Friday':'Friday'):''}"><b>${day}</b>${marker}</span>`)}return `<div class="kahf-calendar"><header><button type="button" data-kahf-month="-1" aria-label="Previous month"><i class="ph ph-caret-left"></i></button><h3>${view.toLocaleString('en-US',{month:'long'})} ${year}</h3><button type="button" data-kahf-month="1" aria-label="Next month"><i class="ph ph-caret-right"></i></button></header><div class="kahf-calendar-weekdays">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(x=>`<span>${x}</span>`).join('')}</div><div class="kahf-calendar-grid">${cells.join('')}</div><div class="kahf-calendar-legend"><span><i class="kahf-legend-swatch is-complete"></i> Complete</span><span><i class="kahf-legend-swatch is-partial"></i> Partial</span><span><i class="kahf-legend-swatch is-upcoming"></i> Upcoming</span></div><a class="kahf-history-link" href="/quran/al-kahf-friday/history" data-route>View Surah Al-Kahf Friday History <i class="ph ph-arrow-right"></i></a></div>`}
function kahfStreaks(){const records=kahfRecords(),keys=Object.keys(records).filter(k=>records[k].status==='partial'||records[k].status==='complete').sort();let longest=0,run=0,prev=null;for(const key of keys){const d=new Date(key+'T12:00:00');if(prev&&Math.round((d-prev)/86400000)===7)run++;else run=1;longest=Math.max(longest,run);prev=d}let current=0,d=new Date(kahfFridayKey()+'T12:00:00');for(let i=0;i<520;i++){const key=quranDateKey(d);if(records[key]?.status==='partial'||records[key]?.status==='complete'){current++;d.setDate(d.getDate()-7)}else break}return {current,longest,full:keys.filter(k=>records[k].status==='complete').length,partial:keys.filter(k=>records[k].status==='partial').length}}

