function sajdahVirtues(){return `<section class="featured-virtues-section"><div class="section-heading"><div><p class="section-eyebrow">From the Sunnah</p><h2>Surah As-Sajdah in the Prophet’s ﷺ practice</h2></div></div><div class="featured-virtues-grid"><article class="featured-virtue-card"><img src="assets/images/quran/as-sajdah/sajdah-section-03.png" alt="A lantern-lit courtyard beneath a star-filled sky" loading="lazy"><span class="featured-virtue-shade"></span><div><p class="section-eyebrow">Before Sleep</p><blockquote>“The Prophet ﷺ would not sleep until he recited Alif-Lām-Mīm Tanzīl and Tabārak alladhī biyadihi al-mulk.”</blockquote><a href="https://sunnah.com/tirmidhi:2892" target="_blank" rel="noopener noreferrer">Jāmiʿ at-Tirmidhī 2892 <i class="ph ph-arrow-square-out"></i></a></div></article><article class="featured-virtue-card"><img src="assets/images/quran/as-sajdah/sajdah-hero.png" alt="A mountain valley beneath a brilliant evening sky" loading="lazy"><span class="featured-virtue-shade"></span><div><p class="section-eyebrow">Friday Fajr</p><blockquote>“The Prophet ﷺ used to recite in the Fajr prayer on Friday: Alif-Lām-Mīm Tanzīl and Hal atā ʿalā al-insān.”</blockquote><a href="https://sunnah.com/bukhari:891" target="_blank" rel="noopener noreferrer">Ṣaḥīḥ al-Bukhārī 891 <i class="ph ph-arrow-square-out"></i></a></div></article></div></section>`}
function otherFeaturedReadings(current){const items=[['al-kahf','Surah 18 • Al-Kahf','/quran/al-kahf-friday'],['as-sajdah','Surah 32 • As-Sajdah','/quran/as-sajdah'],['al-mulk','Surah 67 • Al-Mulk','/quran/al-mulk']].filter(([id])=>id!==current);return `<section class="other-featured-readings"><div><p class="section-eyebrow">Continue exploring</p><h2>Other Featured Readings</h2></div><div class="other-featured-links">${items.map(([,label,route])=>`<a href="${route}" data-route>${label}<i class="ph ph-arrow-right"></i></a>`).join('')}</div></section>`}

function sajdahIndex(){const active=sajdahActive(),done=new Set(active.completedSections||[]),current=Math.min(4,Math.max(1,Number(active.currentSection)||1));return `<section class="vision-page kahf-friday-index featured-reading-landing sajdah-featured-index"><div class="featured-reading-primary-action"><div><p class="section-eyebrow">Nightly Reading</p><strong>${done.size} of 4 sections read</strong></div><a class="button button-primary" href="/quran/as-sajdah/section/${current}" data-route>Open Reader <i class="ph ph-arrow-right"></i></a></div><div class="kahf-index-layout"><main><div class="section-heading"><div><p class="section-eyebrow">Reading sections</p><h2>Read Surah As-Sajdah</h2></div></div><div class="kahf-section-grid sajdah-section-grid">${SAJDAH_SECTIONS.map(x=>`<article class="kahf-section-card${done.has(x.id)?' is-complete':''}"><div class="kahf-section-art is-${x.id}"><img src="assets/images/quran/as-sajdah/${x.art}" alt="" loading="lazy"></div><div><p class="section-eyebrow">Section ${x.id} of 4</p><h3>${esc(x.title)}</h3><strong>Surah 32 • As-Sajdah, ${x.range}</strong><p>${esc(x.summary)}</p><a class="button ${x.id===current?'button-primary':'button-secondary'}" href="/quran/as-sajdah/section/${x.id}" data-route>${done.has(x.id)?'Read Again':x.id===current&&done.size?'Continue':'Read Section'}</a></div>${done.has(x.id)?'<span class="kahf-card-status"><i class="ph ph-check-circle-fill"></i> Read</span>':''}</article>`).join('')}</div>${sajdahVirtues()}${otherFeaturedReadings('as-sajdah')}</main><aside class="kahf-index-sidebar" aria-label="Surah As-Sajdah nightly reading panel"><details class="kahf-experience-card" open><summary><span><i class="ph ph-calendar-dots"></i><strong>Nightly History</strong></span><i class="ph ph-caret-down"></i></summary><div class="kahf-panel-body"><p>Track the nights you read Surah As-Sajdah, including readings completed outside Ummiby.</p>${sajdahCalendar()}</div></details><details class="kahf-experience-card" open><summary><span><i class="ph ph-book-open-text"></i><strong>Current Reading</strong></span><i class="ph ph-caret-down"></i></summary><div class="kahf-panel-body"><dl class="kahf-status-list"><div><dt>Current section</dt><dd>Section ${current} of 4</dd></div><div><dt>Completed</dt><dd>${done.size} of 4 sections</dd></div></dl><a class="button button-primary button-block" href="/quran/as-sajdah/section/${current}" data-route>Open Reader</a></div></details></aside></div></section>`}

function mulkAyatRows(section){const surah=QURAN_DATA.find(x=>x.number===67),ayat=surah.ayahs.filter(x=>x.ayah>=section.start&&x.ayah<=section.end),active=mulkActive(),resumeAyah=Number(active.savedAyah)||0,savedSet=savedAyatSet(),noteSet=ayahNoteSet();const basmalah=section.start===1?`<div class="reader-basmalah" lang="ar" dir="rtl">${BASMALAH_ARABIC}</div>`:'';return `<section class="reader-ayah-list">${basmalah}${ayat.map(x=>{const saved=savedSet.has(savedAyatKey(67,x.ayah)),resume=resumeAyah===x.ayah,hasNote=noteSet.has(savedAyatKey(67,x.ayah));return `<article class="reader-ayah${resume?' is-saved-place':''}${saved?' is-saved-ayah':''}" id="ayah-67-${x.ayah}" data-reader-ayah="${x.ayah}">${readerAyahActions({surah:67,ayah:x.ayah,surahName:'Al-Mulk',saved,resume,hasNote,resumeAttribute:`data-mulk-save-ayah="${x.ayah}"`})}<div class="reader-ayah-translation"><p>${esc(x.translation)}</p></div><p class="reader-ayah-arabic" lang="ar" dir="rtl">${x.arabic} <span class="ayah-end">${x.ayah}</span></p></article>`}).join('')}</section>${readerNoteDialog()}`}
function mulkCompanion(section){const active=mulkActive(),saved=Number(active.savedAyah)||0;return `<aside class="reader-companion"><details class="reader-companion-disclosure" open><summary><span><i class="ph ph-book-open-text"></i><strong>Reading Companion</strong></span><i class="ph ph-caret-down"></i></summary><div class="reader-companion-inner"><header><p class="section-eyebrow">Nightly companion</p><h2>Reading Companion</h2><p>Your place in Surah Al-Mulk and trusted resources for further study.</p></header><section class="reader-progress-card"><h3><i class="ph ph-map-pin"></i> Current Reading</h3><dl><div><dt>Featured Reading</dt><dd>Surah 67 • Al-Mulk</dd></div><div><dt>Current Section</dt><dd>Section ${section.id} of 4</dd></div><div><dt>Saved Place</dt><dd>${saved?`Ayah ${saved}`:'Not saved yet'}</dd></div></dl></section><details class="reader-resource-group" open><summary><span><i class="ph ph-books"></i> Study Sources</span><i class="ph ph-caret-down"></i></summary>${mulkStudyResources()}</details></div></details></aside>`}
function mulkReader(id){const section=MULK_SECTIONS.find(x=>x.id===Number(id));if(!section)return mulkIndex();const prefs=readingPreferences(),active=mulkActive(),done=new Set(active.completedSections||[]);return `<section class="quran-reader reader-framework reader-framework-quran mulk-reader" data-quran-reading-inside data-mulk-section="${section.id}" style="--reader-arabic-size:${prefs.arabicSize}rem"><header class="quran-reader-top reader-framework-top"><a class="quran-reader-exit" href="/quran/al-mulk" data-route data-mulk-return-index="${section.id}"><i class="ph ph-caret-left"></i><span>Al-Mulk Index</span></a><div><span>Surah Al-Mulk • Section ${section.id} of 4</span><strong>Surah 67 • Al-Mulk, ${section.range}</strong><div class="reader-header-progress reader-scroll-progress"><div class="progress-track"><span data-reader-scroll-progress style="width:0%"></span></div><small data-reader-scroll-label>0% through this page</small></div></div><div class="reader-display-controls"><button type="button" data-arabic-size-step="-0.1">A−</button><button type="button" data-arabic-size-step="0.1">A+</button><a class="reader-saved-ayat-shortcut" href="/quran/saved-ayat" data-route aria-label="Open Saved Ayāt" data-tooltip="Open Saved Ayāt"><i class="ph ph-star"></i></a>${readerInfoControl()}</div></header><div class="reader-framework-workspace">${mulkCompanion(section)}<main class="reader-reading-surface"><header class="reader-passage-heading kahf-section-heading"><div class="kahf-reader-banner mulk-reader-banner is-section-${section.id}"><img src="assets/images/quran/al-mulk/${section.art}" alt="" fetchpriority="high"></div><p class="section-eyebrow kahf-section-count">Section ${section.id} of 4</p><h1>${esc(section.title)}</h1><p>Surah 67 • Al-Mulk, ${section.range}</p></header>${mulkAyatRows(section)}</main></div><nav class="quran-reader-controls reader-framework-footer kahf-reader-footer"><a class="kahf-section-index-link" href="/quran/al-mulk" data-route data-mulk-return-index="${section.id}"><i class="ph ph-squares-four"></i><span>Section Index</span></a><div class="reader-control-actions">${section.id>1?`<a href="/quran/al-mulk/section/${section.id-1}" data-route><i class="ph ph-caret-left"></i><span>Previous Section</span></a>`:'<span class="kahf-control-placeholder" aria-hidden="true"></span>'}<button class="reader-center-action${done.has(section.id)?' is-complete':''}" type="button" data-mulk-complete-section="${section.id}" aria-pressed="${done.has(section.id)}"><i class="${done.has(section.id)?'ph-fill':'ph'} ph-check-circle"></i><span>${done.has(section.id)?'Section Read ✓':'Mark Section Read'}</span></button>${section.id<4?`<a href="/quran/al-mulk/section/${section.id+1}" data-route><span>Next Section</span><i class="ph ph-caret-right"></i></a>`:'<button type="button" data-mulk-complete-surah><span>Complete Al-Mulk</span><i class="ph ph-check-circle"></i></button>'}</div></nav>${quranReadingSettings(prefs)}</section>`}

function kahfFridayIndex(){const active=kahfActive(),done=new Set(active.completedSections||[]),current=Math.min(8,Math.max(1,Number(active.currentSection)||1)),section=KAHF_SECTIONS.find(x=>x.id===current)||KAHF_SECTIONS[0],today=new Date();return `<section class="vision-page kahf-friday-index featured-reading-landing"><div class="featured-reading-primary-action"><div><p class="section-eyebrow">Friday Reading</p><strong>${done.size} of 8 sections read this Friday</strong></div><a class="button button-primary" href="/quran/al-kahf-friday/section/${current}" data-route>Open Reader <i class="ph ph-arrow-right"></i></a></div><div class="kahf-index-layout"><main><div class="section-heading"><div><p class="section-eyebrow">Reading sections</p><h2>Read Surah Al-Kahf</h2></div></div><div class="kahf-section-grid">${KAHF_SECTIONS.map(x=>`<article class="kahf-section-card${done.has(x.id)?' is-complete':''}"><div class="kahf-section-art is-${x.id}"><img src="assets/images/quran/al-kahf/${x.art}" alt="" loading="lazy"></div><div><p class="section-eyebrow">Section ${x.id} of 8</p><h3>${esc(x.title)}</h3><strong>Surah 18 • Al-Kahf, ${x.range}</strong><p>${esc(x.summary)}</p><a class="button ${x.id===current?'button-primary':'button-secondary'}" href="/quran/al-kahf-friday/section/${x.id}" data-route>${done.has(x.id)?'Read Again':x.id===current&&done.size?'Continue':'Read Section'}</a></div>${done.has(x.id)?'<span class="kahf-card-status"><i class="ph ph-check-circle-fill"></i> Read this Friday</span>':''}</article>`).join('')}</div>${otherFeaturedReadings('al-kahf')}</main><aside class="kahf-index-sidebar" aria-label="Surah Al-Kahf Friday reading panel">
<details class="kahf-experience-card kahf-current-friday" open><summary><span><i class="ph ph-calendar-blank"></i> Current Friday</span><i class="ph ph-caret-down"></i></summary><div class="kahf-panel-body"><div class="kahf-friday-dates"><strong>${today.toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'})}</strong><span>${kahfHijriDate(today)}</span></div>${kahfCalendar()}</div></details>
<details class="kahf-experience-card kahf-reading-status" open><summary><span><i class="ph ph-book-open-text"></i> Your Reading</span><i class="ph ph-caret-down"></i></summary><div class="kahf-panel-body"><div class="kahf-reading-status-top"><div class="kahf-progress-ring" style="--kahf-progress:${done.size/8*360}deg"><span><strong>${done.size}</strong><small>of 8</small></span></div><div><p class="section-eyebrow">Current section</p><h3>${esc(section.title)}</h3><strong>Surah 18 • Al-Kahf, ${section.range}</strong></div></div><a class="button button-primary" href="/quran/al-kahf-friday/section/${current}" data-route>Continue Reading <i class="ph ph-arrow-right"></i></a></div></details>
<details class="kahf-experience-card kahf-friday-actions" open><summary><span><i class="ph ph-check-square-offset"></i> Friday Actions</span><i class="ph ph-caret-down"></i></summary><div class="kahf-panel-body"><section class="kahf-action-block"><div><h3>Read elsewhere?</h3><p>Record a completed Al-Kahf reading without marking every section as read.</p></div><button class="button button-primary" type="button" data-open-kahf-external>Mark This Friday Complete</button></section><section class="kahf-action-block kahf-reset-block"><div><h3>Begin again</h3><p>Clear this Friday's progress and restart this Friday’s reading.</p></div><button class="button button-secondary" type="button" data-kahf-reset-friday>Reset This Friday</button></section></div></details>
</aside></div><dialog class="confirm-dialog kahf-external-dialog" data-kahf-external-dialog><div class="dialog-header"><div><p class="section-eyebrow">Record external reading</p><h2>Mark This Friday Complete?</h2></div><button type="button" data-close-kahf-external aria-label="Close"><i class="ph ph-x"></i></button></div><p>Did you complete Surah Al-Kahf this Friday outside Ummiby?</p><div class="dialog-actions"><button class="button button-secondary" type="button" data-close-kahf-external>Cancel</button><button class="button button-primary" type="button" data-confirm-kahf-external>Mark Complete</button></div></dialog></section>`}
function readerAyahActions({surah,ayah,surahName,saved,resume,hasNote,resumeAttribute}){const reference=`${surah}:${ayah}`,starLabel=saved?'Remove from Saved Ayāt':'Add to Saved Ayāt',noteLabel=hasNote?'View or edit personal note':'Add personal note',pinLabel=resume?'Current reading place':'Save reading place';return `<div class="reader-ayah-actions"><span class="reader-ayah-number">${reference}</span><button class="reader-ayah-star${saved?' is-saved':''}" type="button" data-toggle-saved-ayah data-saved-surah="${surah}" data-saved-ayah="${ayah}" data-saved-surah-name="${esc(surahName)}" aria-pressed="${saved}" aria-label="${starLabel}" data-tooltip="${starLabel}"><i class="${saved?'ph-fill':'ph'} ph-star" aria-hidden="true"></i></button><button class="reader-ayah-note${hasNote?' has-note':''}" type="button" data-open-ayah-note data-note-surah="${surah}" data-note-ayah="${ayah}" data-note-surah-name="${esc(surahName)}" aria-label="${noteLabel}" data-tooltip="${noteLabel}"><i class="${hasNote?'ph-fill':'ph'} ph-note-pencil" aria-hidden="true"></i></button><button class="reader-ayah-pin${resume?' is-resume':''}" type="button" ${resumeAttribute} aria-label="${pinLabel}" data-tooltip="${pinLabel}"><i class="${resume?'ph-fill':'ph'} ph-map-pin" aria-hidden="true"></i>${resume?'<span>Resume</span>':''}</button></div>`}
function kahfAyatRows(section){const surah=QURAN_DATA.find(x=>x.number===18),ayat=surah.ayahs.filter(x=>x.ayah>=section.start&&x.ayah<=section.end),active=kahfActive(),resumeAyah=Number(active.savedAyah)||0,savedSet=savedAyatSet(),noteSet=ayahNoteSet();const basmalah=section.start===1?`<div class="reader-basmalah" lang="ar" dir="rtl">${BASMALAH_ARABIC}</div>`:'';return `<section class="reader-ayah-list">${basmalah}${ayat.map(x=>{const saved=savedSet.has(savedAyatKey(18,x.ayah)),resume=resumeAyah===x.ayah,hasNote=noteSet.has(savedAyatKey(18,x.ayah));return `<article class="reader-ayah${resume?' is-saved-place':''}${saved?' is-saved-ayah':''}" id="ayah-18-${x.ayah}" data-reader-ayah="${x.ayah}">${readerAyahActions({surah:18,ayah:x.ayah,surahName:'Al-Kahf',saved,resume,hasNote,resumeAttribute:`data-kahf-save-ayah="${x.ayah}"`})}<div class="reader-ayah-translation"><p>${esc(x.translation)}</p></div><p class="reader-ayah-arabic" lang="ar" dir="rtl">${x.arabic} <span class="ayah-end">${x.ayah}</span></p></article>`}).join('')}</section>${readerNoteDialog()}`}

function readerInfoControl(){return `<span class="reader-info-control"><button type="button" class="reader-info-button" data-open-reader-info aria-label="Reader text information"><i class="ph ph-info"></i></button></span><dialog class="reader-info-dialog" data-reader-info-dialog aria-labelledby="reader-info-title"><div><header><span><i class="ph ph-info"></i></span><div><p class="section-eyebrow">Reader information</p><h2 id="reader-info-title">Text used in this reader</h2></div><button type="button" data-close-reader-info aria-label="Close reader information"><i class="ph ph-x"></i></button></header><dl><div><dt>English translation</dt><dd>Hilali &amp; Muhsin Khan</dd></div><div><dt>Arabic text</dt><dd>Tanzil Uthmani text (CC BY 3.0)</dd></div></dl></div></dialog>`}
function kahfStudyResources(){return `<div class="kahf-study-links"><section class="kahf-study-category"><p>Video</p><a href="https://www.youtube.com/watch?v=g21xbap-gB4" target="_blank" rel="noopener noreferrer"><i class="ph ph-video"></i><span><strong>Lessons from Surah Al-Kahf</strong><small>Abū ʿAbd al-Raḥmān Hilāl</small></span><i class="ph ph-arrow-square-out"></i></a></section><section class="kahf-study-category"><p>Audio</p><a href="https://soundcloud.com/salafi-publications/lessons-from-surah-al-kahf-by" target="_blank" rel="noopener noreferrer"><i class="ph ph-headphones"></i><span><strong>Lessons from Surah Al-Kahf</strong><small>Abū ʿAbd al-Raḥmān Hilāl</small></span><i class="ph ph-arrow-square-out"></i></a></section><section class="kahf-study-category"><p>Reading</p><a href="https://salafidawahmanchester.com/2026/02/02/3-some-timeless-lessons-and-reflections-from-surah-al-kahf/" target="_blank" rel="noopener noreferrer"><i class="ph ph-file-text"></i><span><strong>Some Timeless Lessons and Reflections</strong><small>Surah Al-Kahf</small></span><i class="ph ph-arrow-square-out"></i></a></section></div>`}

function kahfCompanion(section){const active=kahfActive(),saved=Number(active.savedAyah)||0;return `<aside class="reader-companion"><details class="reader-companion-disclosure" open><summary><span><i class="ph ph-book-open-text"></i><strong>Reading Companion</strong></span><i class="ph ph-caret-down"></i></summary><div class="reader-companion-inner"><header><p class="section-eyebrow">Friday companion</p><h2>Reading Companion</h2><p>Your Friday reading place, the virtue of Surah Al-Kahf, and trusted study sources.</p></header><section class="kahf-virtue"><h3><i class="ph ph-sun"></i> Virtue of Reading Al-Kahf on Friday</h3><p>“Whoever reads Surah Al-Kahf on Friday, a light will shine for him between the two Fridays.”</p><small>Reported from Abū Saʿīd al-Khudrī; authenticated by al-Albānī in Ṣaḥīḥ al-Jāmiʿ, no. 6470.</small></section><section class="reader-progress-card"><h3><i class="ph ph-map-pin"></i> Current Reading</h3><dl><div><dt>Featured Reading</dt><dd>Surah 18 • Al-Kahf</dd></div><div><dt>Current Section</dt><dd>${section.id} of 8</dd></div><div><dt>Saved Place</dt><dd>${saved?`Surah 18 • Al-Kahf, Ayah ${saved}`:'Not saved yet'}</dd></div></dl></section><details class="reader-resource-group" open><summary><span><i class="ph ph-books"></i> Study Sources</span><i class="ph ph-caret-down"></i></summary>${kahfStudyResources()}</details></div></details></aside>`}

function mulkIndex(){const active=mulkActive(),done=new Set(active.completedSections||[]),current=Math.min(4,Math.max(1,Number(active.currentSection)||1));return `<section class="vision-page kahf-friday-index featured-reading-landing mulk-featured-index"><div class="featured-reading-primary-action"><div><p class="section-eyebrow">Nightly Reading</p><strong>${done.size} of 4 sections read</strong></div><a class="button button-primary" href="/quran/al-mulk/section/${current}" data-route data-mulk-section-link>Open Reader <i class="ph ph-arrow-right"></i></a></div><div class="kahf-index-layout mulk-index-layout"><main><div class="section-heading"><div><p class="section-eyebrow">Reading sections</p><h2>Read Surah Al-Mulk</h2></div></div><div class="kahf-section-grid mulk-section-grid">${MULK_SECTIONS.map(x=>`<article class="kahf-section-card${done.has(x.id)?' is-complete':''}"><div class="kahf-section-art is-${x.id}"><img src="assets/images/quran/al-mulk/${x.art}" alt="" loading="lazy"></div><div><p class="section-eyebrow">Section ${x.id} of 4</p><h3>${esc(x.title)}</h3><strong>Surah 67 • Al-Mulk, ${x.range}</strong><a class="button ${x.id===current?'button-primary':'button-secondary'}" href="/quran/al-mulk/section/${x.id}" data-route data-mulk-section-link>${done.has(x.id)?'Read Again':x.id===current&&done.size?'Continue':'Read Section'}</a></div>${done.has(x.id)?'<span class="kahf-card-status"><i class="ph ph-check-circle-fill"></i> Read</span>':''}</article>`).join('')}</div><section class="mulk-closing-reminder"><img src="assets/images/quran/al-mulk/mulk-section-03.png" alt="Quiet evening path lit by a lantern"><span></span><div><p class="section-eyebrow">A Blessed Surah</p><blockquote>“There is a surah of thirty verses that interceded for a man until he was forgiven. It is: ‘Blessed is He in Whose Hand is dominion.’”</blockquote><a href="https://sunnah.com/abudawud:1400" target="_blank" rel="noopener noreferrer">Sunan Abū Dāwūd 1400 • Jāmiʿ at-Tirmidhī 2891 • Authenticated by al-Albānī <i class="ph ph-arrow-square-out"></i></a></div></section>${otherFeaturedReadings('al-mulk')}</main><aside class="kahf-index-sidebar mulk-index-sidebar" aria-label="Surah Al-Mulk nightly reading panel"><details class="kahf-experience-card mulk-history-card" open><summary><span><i class="ph ph-calendar-dots"></i><strong>Nightly History</strong></span><i class="ph ph-caret-down"></i></summary><div class="kahf-panel-body"><p>Track the nights you read Surah Al-Mulk, including readings completed outside Ummiby.</p>${mulkCalendar()}</div></details><details class="kahf-experience-card" open><summary><span><i class="ph ph-book-open-text"></i><strong>Current Reading</strong></span><i class="ph ph-caret-down"></i></summary><div class="kahf-panel-body"><dl class="kahf-status-list"><div><dt>Current section</dt><dd>Section ${current} of 4</dd></div><div><dt>Completed</dt><dd>${done.size} of 4 sections</dd></div></dl><a class="button button-primary button-block" href="/quran/al-mulk/section/${current}" data-route data-mulk-section-link>Open Reader</a></div></details></aside></div></section>`}

function kahfFridayReader(id){const section=KAHF_SECTIONS.find(x=>x.id===Number(id));if(!section)return kahfFridayIndex();const prefs=readingPreferences(),active=kahfActive(),done=new Set(active.completedSections||[]);return `<section class="quran-reader reader-framework reader-framework-quran kahf-friday-reader" data-quran-reading-inside data-kahf-section="${section.id}" style="--reader-arabic-size:${prefs.arabicSize}rem"><header class="quran-reader-top reader-framework-top"><a class="quran-reader-exit" href="/quran/al-kahf-friday" data-route data-kahf-return-index="${section.id}"><i class="ph ph-caret-left"></i><span>Al-Kahf Index</span></a><div><span>Al-Kahf Friday • Section ${section.id} of 8</span><strong>Surah 18 • Al-Kahf, ${section.range}</strong><div class="reader-header-progress reader-scroll-progress"><div class="progress-track"><span data-reader-scroll-progress style="width:0%"></span></div><small data-reader-scroll-label>0% through this page</small></div></div><div class="reader-display-controls"><button type="button" data-arabic-size-step="-0.1">A−</button><button type="button" data-arabic-size-step="0.1">A+</button><a class="reader-saved-ayat-shortcut" href="/quran/saved-ayat" data-route aria-label="Open Saved Ayāt" data-tooltip="Open Saved Ayāt"><i class="ph ph-star"></i></a>${readerInfoControl()}</div></header><div class="reader-framework-workspace">${kahfCompanion(section)}<main class="reader-reading-surface"><header class="reader-passage-heading kahf-section-heading"><div class="kahf-reader-banner is-section-${section.id}"><img src="assets/images/quran/al-kahf/${section.art}" alt="" fetchpriority="high"></div><p class="section-eyebrow kahf-section-count">Section ${section.id} of 8</p><h1>${esc(section.title)}</h1><p>Surah 18 • Al-Kahf, ${section.range}</p><small>${esc(section.summary)}</small></header>${kahfAyatRows(section)}</main></div><nav class="quran-reader-controls reader-framework-footer kahf-reader-footer"><a class="kahf-section-index-link" href="/quran/al-kahf-friday" data-route data-kahf-return-index="${section.id}"><i class="ph ph-squares-four"></i><span>Section Index</span></a><div class="reader-control-actions">${section.id>1?`<a href="/quran/al-kahf-friday/section/${section.id-1}" data-route><i class="ph ph-caret-left"></i><span>Previous Section</span></a>`:'<span class="kahf-control-placeholder" aria-hidden="true"></span>'}<button class="reader-center-action${done.has(section.id)?' is-complete':''}" type="button" data-kahf-complete-section="${section.id}" aria-pressed="${done.has(section.id)}" title="${done.has(section.id)?'Mark this section unread':'Mark this section read'}"><i class="${done.has(section.id)?'ph-fill':'ph'} ph-check-circle"></i><span>${done.has(section.id)?'Section Read ✓':'Mark Section Read'}</span></button>${section.id<8?`<a href="/quran/al-kahf-friday/section/${section.id+1}" data-route><span>Next Section</span><i class="ph ph-caret-right"></i></a>`:'<button type="button" data-kahf-complete-surah><span>Complete Al-Kahf</span><i class="ph ph-check-circle"></i></button>'}</div></nav>${quranReadingSettings(prefs)}</section>`}

function featuredReadingCard({href,className='',artwork,artworkAlt='',ribbonLabel,ribbonIcon='book-open-text',category,title,subtitle='',citation='',actionLabel='Read',actionIcon='book-open-text',statusHeading,statusText,referenceText='',status='not-started'}){return `<article class="featured-reading-system-card ${className} is-${status}"><img class="featured-reading-system-art" src="${esc(artwork)}" alt="${esc(artworkAlt)}"><span class="featured-reading-system-shade" aria-hidden="true"></span><span class="featured-reading-ribbon" aria-label="${esc(ribbonLabel)}"><i class="ph ph-${esc(ribbonIcon)}" aria-hidden="true"></i><strong>${esc(ribbonLabel)}</strong></span><div class="featured-reading-system-copy"><p class="featured-reading-category">${esc(category)}</p><h2>${esc(title)}</h2>${subtitle?`<blockquote><p>“${esc(subtitle)}”</p>${citation?`<cite>— ${esc(citation)}</cite>`:''}</blockquote>`:''}</div><div class="featured-reading-system-footer"><a class="featured-reading-system-action" href="${esc(href)}" data-route><i class="ph ph-${esc(actionIcon)}" aria-hidden="true"></i><span>${esc(actionLabel)}</span></a><div class="featured-reading-system-status"><p>${esc(statusHeading)}</p><strong><i aria-hidden="true"></i>${esc(statusText)}</strong>${referenceText?`<span>${esc(referenceText)}</span>`:''}</div></div></article>`}
function upcomingFriday(date=new Date()){const friday=new Date(date),delta=(5-friday.getDay()+7)%7;friday.setDate(friday.getDate()+delta);return friday}
function featuredInvitation(){const now=new Date(),isFriday=now.getDay()===5,month=now.getMonth();if(month===1)return featuredReadingCard({href:'/ramadan',className:'ramadan-featured-reading',artwork:'assets/images/quran/al-kahf/friday-hero.webp',ribbonLabel:'Ramadan',ribbonIcon:'moon-stars',category:'RAMADAN READING',title:'Ramadan Central',subtitle:'Continue your Ramadan reading, fasting record, and nightly worship.',actionLabel:'Open',actionIcon:'arrow-right',statusHeading:'CURRENT SEASON',statusText:'Ramadan Companion',status:'in-progress'});const active=kahfActive(),record=kahfRecords()[kahfFridayKey(now)],complete=isFriday&&record?.status==='complete',inProgress=isFriday&&!complete&&((active.completedSections||[]).length>0||Number(active.savedAyah)>0),status=complete?'complete':inProgress?'in-progress':'not-started',actionLabel=complete?'Review':inProgress?'Continue':'Read',actionIcon=complete?'arrow-counter-clockwise':inProgress?'book-open-page':'book-open-text',statusText=complete?'Completed':inProgress?'In Progress':'Not Started',friday=upcomingFriday(now),fridayLabel=`${isFriday?'CURRENT':'UPCOMING'} FRIDAY • ${friday.toLocaleDateString('en-US',{month:'short',day:'numeric'}).toUpperCase()}`;return featuredReadingCard({href:'/quran/al-kahf-friday',className:'kahf-featured-reading',artwork:'assets/images/quran/al-kahf/friday-hero.webp',artworkAlt:'Sunrise viewed from within a cave over a green valley',ribbonLabel:'Friday',ribbonIcon:'seal',category:'FRIDAY READING',title:'Surah Al-Kahf',subtitle:'Whoever reads Surah Al-Kahf on Friday, a light will shine for him between the two Fridays.',citation:'Ṣaḥīḥ al-Jāmiʿ 6470',actionLabel,actionIcon,statusHeading:fridayLabel,statusText,referenceText:'Surah 18 • Al-Kahf',status})}
function quranHome(){const journey=activeJourney(),today=quranReadToday();return `<section class="vision-page quran-vision quran-home-refined"><section class="quran-home-action-grid"><article class="continue-reading-feature"><div class="continue-reading-icon">${visionIcon('book-open-text')}</div><div class="continue-reading-copy"><p class="section-eyebrow">Active Reading Journey</p><h2>${esc(journey.name)}</h2><p>${esc(journey.position)}</p>${progressBar(journey.progress)}<div class="continue-reading-meta"><span>${journey.current} of ${journey.total} ${esc(journey.unitLabel||'')}</span><strong>${journey.progress}% complete</strong></div><a class="button button-primary" href="${journey.continueRoute}" data-route>Continue Reading <i class="ph ph-arrow-right"></i></a></div></article><aside class="quran-home-side"><section class="support-panel weekly-support"><div class="section-heading"><div><p class="section-eyebrow">Have I read today?</p><h3>Weekly Consistency ${quranReadingTooltip()}</h3></div><a class="section-link" href="/quran/history" data-route>View History</a></div><div class="vision-week">${quranWeek().map(d=>`<div class="${d.today?'is-today':''}"><span>${d.label}</span><i class="${d.done?'is-done':''}"></i></div>`).join('')}</div><button class="button ${today?'button-secondary is-done':'button-primary'} quran-record-button" type="button" data-record-quran-today aria-pressed="${today}">${today?'Read Today ✓':'Record Today’s Reading'}</button><p class="consistency-note">Reading inside Ummiby Companion is recorded automatically.</p></section><a class="journey-summary-card" href="/quran/journeys" data-route><div class="section-heading"><div><p class="section-eyebrow">Your saved reading path</p><h3>Reading Journeys</h3></div><i class="ph ph-arrow-up-right"></i></div><strong>${esc(journey.name)}</strong><span>${esc(journey.position)}</span>${progressBar(journey.progress)}<small>${journey.current} of ${journey.total} ${esc(journey.unitLabel||'')}</small></a></aside></section><section class="home-section featured-area"><div class="section-heading"><div><p class="section-eyebrow">Timely companion</p><h3>Featured</h3></div></div>${featuredInvitation()}</section></section>`}
function journeyProgressRing(journey){return `<div class="journey-progress-ring" style="--journey-progress:${Number(journey.progress)||0}%" role="img" aria-label="${Number(journey.progress)||0}% complete"><span><strong>${Number(journey.progress)||0}%</strong><small>complete</small></span></div>`}
function activeJourneyDialog(journey){return `<dialog class="account-dialog journey-active-dialog" id="make-active-${journey.id}" data-active-journey-dialog><form method="dialog"><div class="dialog-heading"><div><p class="page-kicker">Reading Journeys</p><h2>Make Active Reading Journey?</h2></div><button class="dialog-close" value="cancel" aria-label="Cancel"><i class="ph ph-x" aria-hidden="true"></i></button></div><p>Your Continue Reading card will now resume this Reading Journey.</p><p>Your progress in both Reading Journeys will be preserved.</p><div class="dialog-actions"><button class="button button-secondary" value="cancel">Cancel</button><button class="button button-primary" type="button" data-confirm-active-journey="${journey.id}">Make Active</button></div></form></dialog>`}
function journeyExperienceCard(journey,{eyebrow,iconName,purpose,features,definition=''}){const active=journeyState().activeId===journey.id;return `<article class="reading-journey-card${active?' is-active':''}"><header class="reading-journey-card-header"><div class="reading-journey-title"><span class="journey-card-icon">${visionIcon(iconName)}</span><div><p class="section-eyebrow">${esc(eyebrow)}</p><h2>${esc(journey.name)}</h2></div></div>${active?'<span class="active-journey-badge"><i class="ph ph-check-circle-fill" aria-hidden="true"></i> Active Journey</span>':''}</header><p class="journey-purpose"><strong>Purpose</strong>${esc(purpose)}</p><section class="journey-unique"><h3>What makes this journey unique?</h3><ul>${features.map(item=>`<li><i class="ph ph-check" aria-hidden="true"></i><span>${esc(item)}</span></li>`).join('')}</ul></section>${definition?`<aside class="reading-unit-definition"><h3>What is a reading unit?</h3><p>${esc(definition)}</p></aside>`:''}<div class="journey-card-progress"><div><span>${esc(journey.position)}</span>${progressBar(journey.progress)}<small>${journey.current} of ${journey.total} ${esc(journey.unitLabel)}</small></div><strong>${journey.progress}%</strong></div><div class="journey-actions"><a class="button button-primary" href="${journey.continueRoute}" data-route>Continue Reading</a><a class="button button-secondary" href="${journey.indexRoute}" data-route>View Journey</a>${active?'':`<button class="button button-secondary make-active-button" type="button" data-open-active-journey="${journey.id}">Make Active</button>`}</div>${active?'':activeJourneyDialog(journey)}</article>`}
function journeysPage(){const state=journeyState(),active=state.journeys[state.activeId],unit=state.journeys['reading-unit'],classic=state.journeys.classic;return `<section class="vision-page reading-journeys-page"><section class="reading-journeys-introduction"><h2>What is a Reading Journey?</h2><p>Reading Journeys are structured ways to read the Qur’an over time.</p><p>Each journey remembers your place, tracks your progress, and allows you to continue where you left off.</p><p>You may participate in multiple Reading Journeys while selecting one as your Active Journey for quick access from the Qur’an Home page.</p></section><aside class="reading-order-callout"><i class="ph ph-info" aria-hidden="true"></i><div><h2>Both Reading Journeys follow the Qur’an in its traditional order.</h2><p>The difference is simply how your reading is organized and resumed.</p><p>Choose the approach that best supports your personal reading routine.</p></div></aside><section class="active-journey-section"><div class="active-journey-copy"><p class="section-eyebrow">Active Journey</p><h2>${esc(active.name)}</h2><p>${esc(active.position)}</p>${progressBar(active.progress)}<div class="active-journey-meta"><span>${active.current} of ${active.total} ${esc(active.unitLabel)}</span><strong>${active.progress}% complete</strong></div><div class="journey-actions"><a class="button button-primary" href="${active.continueRoute}" data-route>Continue Reading</a><a class="button button-secondary" href="${active.indexRoute}" data-route>View Journey</a></div></div>${journeyProgressRing(active)}</section><section class="journey-detail-grid">${journeyExperienceCard(unit,{eyebrow:'294 manageable reading units',iconName:'book-open-text',purpose:'Read the Qur’an from beginning to end in its traditional order through thoughtfully organized reading units that encourage steady progress and reflection.',features:['Follows the Qur’an in its traditional order.','Divides the reading into 294 manageable reading units.','Provides natural places to pause and resume.','Highlights the main themes of each unit.','Includes contextual study resources when available.','Remembers your progress automatically.'],definition:'A reading unit is a thoughtfully chosen section of the Qur’an that follows the traditional order while creating a natural place to pause, reflect, and continue your reading later.'})}${journeyExperienceCard(classic,{eyebrow:'114 surahs, your stopping points',iconName:'books',purpose:'Read the Qur’an from beginning to end in its traditional surah order while remembering exactly where you stopped—even in the middle of a surah.',features:['Follows the Qur’an in its traditional order.','Organized by surahs rather than reading units.','Resume from any ayah, even if you stopped partway through a surah.','Complete each surah at your own pace.','Includes contextual study resources when available.','Remembers your progress automatically.']})}</section><section class="journey-comparison-section"><div class="section-heading"><div><p class="section-eyebrow">Choose what supports your routine</p><h2>Which Reading Journey is Right for Me?</h2></div></div><div class="journey-comparison-grid"><article><h3>Reading Unit Journey</h3><p>Best if you prefer:</p><ul><li>Shorter daily reading sessions</li><li>Natural stopping points</li><li>Reflection after each reading unit</li><li>Smaller, manageable milestones</li></ul></article><article><h3>Classic Journey</h3><p>Best if you prefer:</p><ul><li>Reading through the Qur’an in traditional surah order</li><li>Choosing your own stopping points</li><li>Resuming from any ayah where you left off</li><li>Celebrating the completion of each surah over time</li></ul></article></div></section><aside class="active-journey-explanation"><span class="journey-card-icon">${visionIcon('signpost')}</span><div><h2>Understanding Your Active Journey</h2><p>Your Active Journey determines which reading path appears on the Qur’an Home page.</p><p>The Continue Reading card always resumes your Active Journey.</p><p>You may keep progress in multiple Reading Journeys at the same time.</p><p>Changing your Active Journey never removes or resets your progress.</p></div></aside></section>`}
function navigatorPage(){const surahs=QURAN_DATA.map(surah=>`<a class="navigator-surah-tile" href="/quran/navigator/${surah.number}" data-route data-navigator-surah data-surah-search="${esc(`${surah.number} ${surah.name} ${surah.englishName||''}`.toLowerCase())}"><span>${surah.number}</span><strong>${esc(surah.name)}</strong><small>${surah.ayahs.length} Ayat</small></a>`).join('');return `<section class="vision-page navigator-page"><header class="editorial-header"><p class="page-kicker">Unrestricted reading</p><h2>Qur’an Navigator</h2><p>Browse the complete Qur’an by surah. Reading here counts toward daily consistency without changing journey progress.</p></header><section class="navigator-toolbar"><label><i class="ph ph-magnifying-glass"></i><input type="search" placeholder="Find a surah by number or name" aria-label="Find a surah" data-navigator-search></label><button class="button button-secondary" type="button" data-reader-placeholder><i class="ph ph-crosshair"></i> Jump to Ayah</button></section><div class="navigator-surah-grid">${surahs}</div><p class="navigator-results" data-navigator-results>114 surahs shown</p></section>`}

function quranHistoryYearOptions(selectedYear){
  const records=quranReadingDays(),currentYear=new Date().getFullYear();
  const years=Object.keys(records).map(key=>Number(key.slice(0,4))).filter(Number.isInteger);
  const earliest=Math.min(2026,...years),latest=Math.max(currentYear+1,selectedYear);
  return Array.from({length:latest-earliest+1},(_,index)=>latest-index).map(year=>`<option value="${year}"${year===selectedYear?' selected':''}>${year}</option>`).join('');
}
function quranHistoryStats(){
  const dates=Object.keys(quranReadingDays()).filter(key=>quranReadingDays()[key]).sort();
  let longest=0,run=0,previous=null;
  dates.forEach(key=>{const date=new Date(`${key}T12:00:00`);run=previous&&Math.round((date-previous)/86400000)===1?run+1:1;longest=Math.max(longest,run);previous=date;});
  let current=0,cursor=new Date();
  const today=historyDateKey(cursor),yesterday=new Date(cursor);yesterday.setDate(yesterday.getDate()-1);
  if(!quranReadingDays()[today]&&quranReadingDays()[historyDateKey(yesterday)])cursor=yesterday;
  while(quranReadingDays()[historyDateKey(cursor)]){current+=1;cursor.setDate(cursor.getDate()-1)}
  return {recordedDays:dates.length,currentStreak:current,longestStreak:longest};
}
function quranHistoryCalendar(view){
  const records=quranReadingDays(),today=historyDateKey(new Date()),month=new Date(view.year,view.month,1),firstDay=month.getDay(),daysInMonth=new Date(view.year,view.month+1,0).getDate(),cells=[];
  const previousMonth=new Date(view.year,view.month,0).getDate();
  for(let i=firstDay-1;i>=0;i--)cells.push({day:previousMonth-i,outside:true,date:new Date(view.year,view.month-1,previousMonth-i)});
  for(let day=1;day<=daysInMonth;day++)cells.push({day,outside:false,date:new Date(view.year,view.month,day)});
  let next=1;while(cells.length%7)cells.push({day:next++,outside:true,date:new Date(view.year,view.month+1,next-1)});
  return `<section class="history-calendar-card"><header class="history-calendar-header"><button class="history-month-button" type="button" data-quran-history-month="-1" aria-label="Previous month"><i class="ph ph-caret-left"></i></button><div class="history-calendar-heading"><p class="section-eyebrow">Monthly record</p><h3>${month.toLocaleDateString('en-US',{month:'long'})}</h3><label class="history-year-jump"><span>Jump to year</span><select data-quran-history-year aria-label="Jump to year">${quranHistoryYearOptions(view.year)}</select></label></div><button class="history-month-button" type="button" data-quran-history-month="1" aria-label="Next month"><i class="ph ph-caret-right"></i></button></header><p class="history-calendar-help"><i class="ph ph-pencil-simple" aria-hidden="true"></i> Select today or a past date to record Qur’an reading completed outside Ummiby or correct your history.</p><div class="history-weekdays" aria-hidden="true">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(day=>`<span>${day}</span>`).join('')}</div><div class="history-calendar-grid">${cells.map(cell=>{const key=historyDateKey(cell.date),done=Boolean(records[key]),future=key>today;return `<button type="button" class="history-day${cell.outside?' is-outside':''}${done?' is-active is-complete':''}${key===today?' is-today':''}${future?' is-future':''}" data-edit-quran-day="${key}" ${future?'disabled':''} aria-label="${key}: ${done?'Qur’an reading recorded':future?'Future date':'No reading recorded'}. ${future?'Not editable':'Select to edit daily activity'}"><span>${cell.day}</span>${done?'<i aria-hidden="true"></i>':''}</button>`}).join('')}</div><footer class="history-legend"><span><i class="is-complete"></i>Qur’an read</span><span><i class="is-today"></i>Today</span></footer></section>`;
}
function quranMonthInsights(view){
  const records=quranReadingDays(),today=new Date(),monthStart=new Date(view.year,view.month,1),monthEnd=new Date(view.year,view.month+1,0),isCurrent=view.year===today.getFullYear()&&view.month===today.getMonth(),future=monthStart>new Date(today.getFullYear(),today.getMonth(),today.getDate()),through=isCurrent?today:monthEnd;
  const eligible=future?0:Math.max(0,Math.min(monthEnd.getDate(),through.getDate()));
  const dates=Object.keys(records).filter(key=>{if(!records[key])return false;const date=new Date(`${key}T12:00:00`);return date.getFullYear()===view.year&&date.getMonth()===view.month&&date<=through}).sort();
  let longest=0,run=0,previous=null;dates.forEach(key=>{const date=new Date(`${key}T12:00:00`);run=previous&&Math.round((date-previous)/86400000)===1?run+1:1;longest=Math.max(longest,run);previous=date});
  const rate=eligible?Math.round(dates.length/eligible*100):0,monthLabel=monthStart.toLocaleDateString('en-US',{month:'long',year:'numeric'});
  let message=future?`${monthLabel} has not begun yet.`:dates.length?`You read Qur’an on ${dates.length} ${dates.length===1?'day':'days'} this month.`:'No Qur’an reading has been recorded for this month yet.';
  return `<section class="history-insights-card"><p class="section-eyebrow">Monthly insights</p><h3>${monthLabel}</h3>${future?'':`<div class="history-insight-list"><div><i class="ph ph-calendar-check"></i><span><small>Reading days</small><strong>${dates.length} of ${eligible} days</strong></span></div><div><i class="ph ph-chart-donut"></i><span><small>Monthly consistency</small><strong>${rate}%</strong></span></div><div><i class="ph ph-fire"></i><span><small>Longest monthly streak</small><strong>${longest} ${longest===1?'day':'days'}</strong></span></div></div>`}<div class="history-encouragement"><i class="ph ph-sparkle"></i><p>${message}</p></div></section>`;
}
function readingHistoryPage(view={}){
  const now=new Date(),normalized={year:Number.isInteger(view.year)?view.year:now.getFullYear(),month:Number.isInteger(view.month)?view.month:now.getMonth()},progress=readingJourneyProgress(),stats=quranHistoryStats();
  const monthRecords=quranReadingDays(),monthStart=new Date(normalized.year,normalized.month,1),monthEnd=new Date(normalized.year,normalized.month+1,0),todayStart=new Date(now.getFullYear(),now.getMonth(),now.getDate()),isCurrentMonth=normalized.year===now.getFullYear()&&normalized.month===now.getMonth(),futureMonth=monthStart>todayStart,eligibleDays=futureMonth?0:(isCurrentMonth?now.getDate():monthEnd.getDate()),activeThisMonth=Object.keys(monthRecords).filter(key=>{if(!monthRecords[key])return false;const date=new Date(`${key}T12:00:00`);return date.getFullYear()===normalized.year&&date.getMonth()===normalized.month&&date<=todayStart}).length,completionRate=eligibleDays?Math.round(activeThisMonth/eligibleDays*100):0;
  return `<section class="duaa-history-page quran-reading-history-page"><header class="history-page-intro"><p class="section-eyebrow">Every reading day counts</p><h2>Your Qur’an reading history</h2><p>See your daily reading pattern, record reading completed outside Ummiby, and correct past days from one shared calendar.</p></header><section class="history-summary-grid quran-history-summary"><article><span>Active Days</span><div class="history-kpi-value"><i class="ph ph-calendar-check"></i><strong>${stats.recordedDays}</strong></div></article><article><span>Units Completed</span><div class="history-kpi-value"><i class="ph ph-seal-check"></i><strong>${progress.count}</strong></div></article><article><span>Completion Rate</span><div class="history-kpi-value"><i class="ph ph-chart-donut"></i><strong>${completionRate}%</strong></div></article><article><span>Current Streak</span><div class="history-kpi-value"><i class="ph ph-fire"></i><strong>${stats.currentStreak}</strong></div></article><article><span>Longest Streak</span><div class="history-kpi-value"><i class="ph ph-trophy"></i><strong>${stats.longestStreak}</strong></div></article></section><div class="history-workspace">${quranHistoryCalendar(normalized)}${quranMonthInsights(normalized)}</div><dialog class="daily-activity-dialog" data-quran-day-dialog><form method="dialog" class="daily-activity-card"><header><div><p class="section-eyebrow">Record Qur’an Activity</p><h3 data-quran-day-title>Selected date</h3><p>Record reading completed outside Ummiby or correct this day’s history.</p></div><button type="button" class="dialog-close" data-close-quran-day aria-label="Close"><i class="ph ph-x"></i></button></header><div class="daily-activity-options quran-daily-activity-options"><label><input type="checkbox" data-quran-day-activity><span class="daily-activity-icon"><i class="ph ph-book-open-text"></i></span><span><strong>Read Qur’an</strong><small>Count this as a Qur’an reading day</small></span><i class="ph ph-check-circle" aria-hidden="true"></i></label></div><p class="daily-activity-note"><i class="ph ph-info"></i> A day counts once, even when you read in more than one part of Ummiby.</p><footer><button type="button" class="button button-secondary" data-close-quran-day>Cancel</button><button type="button" class="button button-primary" data-save-quran-day>Save Changes</button></footer></form></dialog></section>`;
}


function featuredHistoryConfig(kind){
  const configs={
    kahf:{title:'Surah Al-Kahf Friday History',subtitle:'Track your weekly Friday recitation of Surah Al-Kahf.',schedule:'Weekly • Fridays',label:'Al-Kahf read',unit:'Fridays',storage:'ummiby.quran.kahfFriday.records',route:'/quran/al-kahf-friday',fridayOnly:true,icon:'sun-horizon'},
    mulk:{title:'Surah Al-Mulk Reading History',subtitle:'Track your nightly recitation of Surah Al-Mulk.',schedule:'Nightly • Every day',label:'Al-Mulk read',unit:'Nights',storage:'ummiby.quran.mulkFeatured.records',route:'/quran/al-mulk',fridayOnly:false,icon:'moon-stars'},
    sajdah:{title:'Surah As-Sajdah Reading History',subtitle:'Track your nightly recitation of Surah As-Sajdah.',schedule:'Nightly • Every day',label:'As-Sajdah read',unit:'Nights',storage:'ummiby.quran.sajdahFeatured.records',route:'/quran/as-sajdah',fridayOnly:false,icon:'moon'}
  };return configs[kind]||configs.mulk;
}
function featuredHistoryRecords(kind){const config=featuredHistoryConfig(kind);try{return JSON.parse(localStorage.getItem(config.storage)||'{}')}catch{return {}}}
function featuredHistoryDone(record){return Boolean(record&&(record.status==='complete'||record.completed===true||record.source));}
function featuredHistoryStats(kind){const config=featuredHistoryConfig(kind),records=featuredHistoryRecords(kind),today=new Date(),todayKey=historyDateKey(today);const keys=Object.keys(records).filter(k=>k<=todayKey&&featuredHistoryDone(records[k])).sort();let longest=0,run=0,prev=null;for(const key of keys){const d=new Date(`${key}T12:00:00`),gap=prev?Math.round((d-prev)/86400000):null,needed=config.fridayOnly?7:1;run=gap===needed?run+1:1;longest=Math.max(longest,run);prev=d}let current=0,d=new Date(`${todayKey}T12:00:00`);if(config.fridayOnly){const delta=(d.getDay()-5+7)%7;d.setDate(d.getDate()-delta)}for(let i=0;i<730;i++){const key=historyDateKey(d);if(featuredHistoryDone(records[key])){current++;d.setDate(d.getDate()-(config.fridayOnly?7:1))}else break}return {active:keys.length,completed:keys.length,current,longest};}
function featuredHistoryCalendar(kind,view){const config=featuredHistoryConfig(kind),records=featuredHistoryRecords(kind),today=historyDateKey(new Date()),month=new Date(view.year,view.month,1),first=month.getDay(),days=new Date(view.year,view.month+1,0).getDate(),cells=[];const prevDays=new Date(view.year,view.month,0).getDate();for(let i=first-1;i>=0;i--)cells.push({day:prevDays-i,outside:true,date:new Date(view.year,view.month-1,prevDays-i)});for(let day=1;day<=days;day++)cells.push({day,outside:false,date:new Date(view.year,view.month,day)});let next=1;while(cells.length%7)cells.push({day:next++,outside:true,date:new Date(view.year,view.month+1,next-1)});return `<section class="history-calendar-card"><header class="history-calendar-header"><button class="history-month-button" type="button" data-featured-history-month="-1"><i class="ph ph-caret-left"></i></button><div class="history-calendar-heading"><p class="section-eyebrow">${config.schedule}</p><h3>${month.toLocaleDateString('en-US',{month:'long',year:'numeric'})}</h3></div><button class="history-month-button" type="button" data-featured-history-month="1"><i class="ph ph-caret-right"></i></button></header><p class="history-calendar-help"><i class="ph ph-pencil-simple"></i> ${config.fridayOnly?'Select a past or current Friday':'Select today or a past date'} to record or correct this Surah’s reading.</p><div class="history-weekdays">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(x=>`<span>${x}</span>`).join('')}</div><div class="history-calendar-grid">${cells.map(cell=>{const key=historyDateKey(cell.date),future=key>today,eligible=!config.fridayOnly||cell.date.getDay()===5,done=featuredHistoryDone(records[key]),disabled=future||!eligible;return `<button type="button" class="history-day${cell.outside?' is-outside':''}${done?' is-active is-complete':''}${key===today?' is-today':''}${disabled?' is-future':''}${!eligible?' is-ineligible':''}" data-edit-featured-day="${key}" ${disabled?'disabled':''}><span>${cell.day}</span>${done?'<i aria-hidden="true"></i>':''}</button>`}).join('')}</div><footer class="history-legend"><span><i class="is-complete"></i>${config.label}</span><span><i class="is-today"></i>Today</span></footer></section>`}
function featuredHistoryInsights(kind,view){const config=featuredHistoryConfig(kind),records=featuredHistoryRecords(kind),now=new Date(),end=new Date(view.year,view.month+1,0),isCurrent=view.year===now.getFullYear()&&view.month===now.getMonth(),through=isCurrent?now:end;let eligible=0,completed=0;for(let d=1;d<=through.getDate();d++){const date=new Date(view.year,view.month,d);if(config.fridayOnly&&date.getDay()!==5)continue;eligible++;if(featuredHistoryDone(records[historyDateKey(date)]))completed++}const rate=eligible?Math.round(completed/eligible*100):0;return `<section class="history-insights-card"><p class="section-eyebrow">Monthly insights</p><h3>${new Date(view.year,view.month,1).toLocaleDateString('en-US',{month:'long',year:'numeric'})}</h3><div class="history-insight-list"><div><i class="ph ph-calendar-check"></i><span><small>Completed ${config.unit.toLowerCase()}</small><strong>${completed} of ${eligible}</strong></span></div><div><i class="ph ph-chart-donut"></i><span><small>Completion rate</small><strong>${rate}%</strong></span></div><div><i class="ph ph-clock"></i><span><small>Tracking schedule</small><strong>${config.schedule}</strong></span></div></div></section>`}
function featuredHistoryPage(kind,view={}){const config=featuredHistoryConfig(kind),now=new Date(),normalized={year:Number.isInteger(view.year)?view.year:now.getFullYear(),month:Number.isInteger(view.month)?view.month:now.getMonth()},stats=featuredHistoryStats(kind),records=featuredHistoryRecords(kind);let eligible=0,done=0;for(let d=1;d<=now.getDate();d++){const date=new Date(now.getFullYear(),now.getMonth(),d);if(config.fridayOnly&&date.getDay()!==5)continue;eligible++;if(featuredHistoryDone(records[historyDateKey(date)]))done++}const rate=eligible?Math.round(done/eligible*100):0;return `<section class="duaa-history-page featured-surah-history-page" data-featured-history-kind="${kind}"><header class="history-page-intro"><p class="section-eyebrow">${config.schedule}</p><h2>${config.title}</h2><p>${config.subtitle}</p><a class="section-link" href="${config.route}" data-route>Return to Surah reading</a></header><section class="history-summary-grid"><article><span>Active ${config.unit}</span><div class="history-kpi-value"><i class="ph ph-calendar-check"></i><strong>${stats.active}</strong></div></article><article><span>Completed ${config.unit}</span><div class="history-kpi-value"><i class="ph ph-seal-check"></i><strong>${stats.completed}</strong></div></article><article><span>Completion Rate</span><div class="history-kpi-value"><i class="ph ph-chart-donut"></i><strong>${rate}%</strong></div></article><article><span>Current Streak</span><div class="history-kpi-value"><i class="ph ph-fire"></i><strong>${stats.current}</strong></div></article><article><span>Longest Streak</span><div class="history-kpi-value"><i class="ph ph-trophy"></i><strong>${stats.longest}</strong></div></article></section><div class="history-workspace">${featuredHistoryCalendar(kind,normalized)}${featuredHistoryInsights(kind,normalized)}</div><dialog class="daily-activity-dialog" data-featured-day-dialog><form method="dialog" class="daily-activity-card"><header><div><p class="section-eyebrow">Record ${config.label}</p><h3 data-featured-day-title>Selected date</h3><p>${config.subtitle}</p></div><button type="button" class="dialog-close" data-close-featured-day><i class="ph ph-x"></i></button></header><div class="daily-activity-options quran-daily-activity-options"><label><input type="checkbox" data-featured-day-activity><span class="daily-activity-icon"><i class="ph ph-${config.icon}"></i></span><span><strong>${config.label}</strong><small>Count this date in this Surah’s history</small></span><i class="ph ph-check-circle"></i></label></div><footer><button type="button" class="button button-secondary" data-close-featured-day>Cancel</button><button type="button" class="button button-primary" data-save-featured-day>Save Changes</button></footer></form></dialog></section>`}

function quranSettingsPage(){const prefs=readingPreferences();return `<section class="vision-page"><header class="editorial-header"><p class="page-kicker">Qur’an display</p><h2>Settings</h2><p>Reading preferences remain shared across journeys, Featured Readings, and the Qur’an Navigator.</p></header><section class="settings-page-card"><label class="range-field" for="quran-page-arabic-size"><span>Arabic text size</span><input id="quran-page-arabic-size" type="range" min="1.7" max="3.4" step="0.1" value="${prefs.arabicSize}" data-reading-size><output data-size-output>${prefs.arabicSize.toFixed(1)}rem</output></label><div class="settings-row"><span><strong>Translation display</strong><small>Hilali & Muhsin Khan</small></span><span class="status-pill">Enabled</span></div></section></section>`}

function normalizeReadingUnitOrder(value){const order=Number(value);return Number.isInteger(order)&&order>=1&&order<=QURAN_CANONICAL_STATUS.readingUnits?order:1}
function readingUnitStorageKey(order){return `ummiby.quran.readingUnit.${normalizeReadingUnitOrder(order)}`}
function readingJourneyProgress(){
  let current=1;
  try{
    const storedCurrent=localStorage.getItem('ummiby.quran.readingUnit.current');
    const phaseOneProgress=localStorage.getItem('ummiby.quran.readingUnit.25')||localStorage.getItem('ummiby.quran.readingUnit.87');
    current=normalizeReadingUnitOrder(storedCurrent||(phaseOneProgress?25:1));
  }catch{}
  const completed=[];
  for(let order=1;order<=QURAN_CANONICAL_STATUS.readingUnits;order+=1){
    try{if(JSON.parse(localStorage.getItem(readingUnitStorageKey(order))||'{}').completed)completed.push(order)}catch{}
  }
  const legacyCovered=[];
  for(let order=1;order<=QURAN_CANONICAL_STATUS.readingUnits;order+=1){
    try{if(JSON.parse(localStorage.getItem(readingUnitStorageKey(order))||'{}').previouslyCovered)legacyCovered.push(order)}catch{}
  }
  const completedSet=new Set([...completed,...legacyCovered]);
  return {current,completed:[...completedSet].sort((a,b)=>a-b),count:completedSet.size,percent:Math.round((completedSet.size/QURAN_CANONICAL_STATUS.readingUnits)*100)};
}
function readingUnitProgress(order){
  const normalized=normalizeReadingUnitOrder(order);
  try{
    const current=JSON.parse(localStorage.getItem(readingUnitStorageKey(normalized))||'null');
    if(current)return current;
    if(normalized===25){const legacy=JSON.parse(localStorage.getItem('ummiby.quran.readingUnit.87')||'null');return legacy||{}}
  }catch{}
  return {};
}

function readingUnitHistory(){
  try{return JSON.parse(localStorage.getItem('ummiby.quran.readingUnit.history')||'[]')}catch{return []}
}
function readingUnitState(order,currentOrder){
  const progress=readingUnitProgress(order);
  if(progress.completed)return 'completed';
  if(progress.previouslyCovered)return 'completed';
  if(order===currentOrder||progress.resumeAyah)return 'current';
  return 'not-started';
}
function readingActivityLabel(entry){
  if(entry.type==='completed')return 'Completed';
  if(entry.type==='reopened')return 'Completion removed';
  if(entry.type==='saved')return `Saved place at Ayah ${entry.ayah}`;
  return 'Opened for reading';
}
const QURAN_SAVED_AYAT_KEY='ummiby.quran.savedAyat';
function savedAyatRecords(){
  try{const value=JSON.parse(localStorage.getItem(QURAN_SAVED_AYAT_KEY)||'[]');return Array.isArray(value)?value:[]}catch{return []}
}
function savedAyatKey(surah,ayah){return `${Number(surah)}:${Number(ayah)}`}
function savedAyatSet(){return new Set(savedAyatRecords().map(item=>savedAyatKey(item.surah,item.ayah)))}
function ayahNotes(){try{const value=JSON.parse(localStorage.getItem('ummiby.quran.ayahNotes')||'{}');return value&&typeof value==='object'&&!Array.isArray(value)?value:{}}catch{return {}}}
function ayahNote(surah,ayah){return ayahNotes()[savedAyatKey(surah,ayah)]||null}
function ayahNoteSet(){return new Set(Object.entries(ayahNotes()).filter(([,value])=>value&&String(value.text||'').trim()).map(([key])=>key))}
function readerNoteDialog(){return `<dialog class="ayah-note-dialog" data-ayah-note-dialog><form method="dialog" class="ayah-note-form"><header><span class="vision-icon"><i class="ph ph-note-pencil"></i></span><div><p class="section-eyebrow">Private reflection</p><h2 data-note-dialog-title>Personal Note</h2></div><button class="icon-button" type="button" data-close-ayah-note aria-label="Close note"><i class="ph ph-x"></i></button></header><p>Record a private reflection, lesson, or reminder connected to this ayah.</p><textarea data-ayah-note-text maxlength="2000" rows="8" placeholder="Write your note here…"></textarea><div class="ayah-note-meta"><small data-ayah-note-count>0 / 2000</small><small data-ayah-note-edited></small></div><footer><button class="button button-quiet ayah-note-delete" type="button" data-delete-ayah-note hidden>Delete Note</button><span></span><button class="button button-secondary" type="button" data-close-ayah-note>Cancel</button><button class="button button-primary" type="button" data-save-ayah-note>Save Note</button></footer></form></dialog>`}
function readerNotesList(limit=6){const records=Object.entries(ayahNotes()).filter(([,v])=>v&&String(v.text||'').trim()).map(([key,v])=>{const [surah,ayah]=key.split(':').map(Number);return {surah,ayah,...v}}).sort((a,b)=>a.surah-b.surah||a.ayah-b.ayah);if(!records.length)return `<div class="reader-saved-empty"><i class="ph ph-note-pencil"></i><p>No personal notes yet.</p><small>Select the note icon beside an ayah to write one.</small></div>`;return `<div class="reader-saved-ayat-list reader-note-list">${records.slice(0,limit).map(item=>`<a href="${savedAyahReaderRoute(item.surah,item.ayah)}" data-route data-open-saved-ayah="${item.surah}:${item.ayah}"><span>${item.surah}:${item.ayah}</span><strong>${esc(String(item.text).slice(0,52))}${String(item.text).length>52?'…':''}</strong><i class="ph ph-arrow-right"></i></a>`).join('')}</div>`}
function isAyahSaved(surah,ayah){return savedAyatSet().has(savedAyatKey(surah,ayah))}
function savedAyahReaderRoute(surah,ayah){
  if(Number(surah)===18){const section=KAHF_SECTIONS.find(item=>Number(ayah)>=item.start&&Number(ayah)<=item.end);if(section)return `/quran/al-kahf-friday/section/${section.id}`}
  const unit=QURAN_READING_LIBRARY.units.find(item=>item.surahNumber===Number(surah)&&Number(ayah)>=item.startAyah&&Number(ayah)<=item.endAyah);
  return unit?`/quran/reading-unit/${unit.order}`:`/quran/navigator/${surah}`;
}
function readerSavedAyatList(limit=8){
  const records=savedAyatRecords().sort((a,b)=>a.surah-b.surah||a.ayah-b.ayah);
  if(!records.length)return `<div class="reader-saved-empty"><i class="ph ph-star"></i><p>No Saved Ayāt yet.</p><small>Select the star beside any ayah to keep it here.</small></div>`;
  return `<div class="reader-saved-ayat-list">${records.slice(0,limit).map(item=>`<a href="${savedAyahReaderRoute(item.surah,item.ayah)}" data-route data-open-saved-ayah="${item.surah}:${item.ayah}"><span>${item.surah}:${item.ayah}</span><strong>${esc(item.surahName||`Surah ${item.surah}`)}</strong><i class="ph ph-arrow-right"></i></a>`).join('')}</div>${records.length>limit?`<a class="reader-saved-all-link" href="/quran/saved-ayat" data-route>View all ${records.length} Saved Ayāt <i class="ph ph-arrow-right"></i></a>`:''}`;
}
function readingUnitAyatRows(unit,ayat){const progress=readingUnitProgress(unit.order),resumeAyah=Number(progress.resumeAyah)||0,savedSet=savedAyatSet(),noteSet=ayahNoteSet();const basmalah=unit.startAyah===1&&unit.surahNumber!==1&&unit.surahNumber!==9?`<div class="reader-basmalah" lang="ar" dir="rtl" aria-label="Basmalah">${BASMALAH_ARABIC}</div>`:'';return `<section class="reader-ayah-list" aria-label="${esc(unit.surahName)} ayat ${unit.startAyah} through ${unit.endAyah}">${basmalah}${ayat.map(ayah=>{const saved=savedSet.has(savedAyatKey(unit.surahNumber,ayah.ayah)),resume=resumeAyah===ayah.ayah,hasNote=noteSet.has(savedAyatKey(unit.surahNumber,ayah.ayah));return `<article class="reader-ayah${resume?' is-saved-place':''}${saved?' is-saved-ayah':''}" id="ayah-${unit.surahNumber}-${ayah.ayah}" data-reader-ayah="${ayah.ayah}">${readerAyahActions({surah:unit.surahNumber,ayah:ayah.ayah,surahName:unit.surahName,saved,resume,hasNote,resumeAttribute:`data-select-resume-ayah="${ayah.ayah}"`})}<div class="reader-ayah-translation"><p>${esc(ayah.translation)}</p></div><p class="reader-ayah-arabic" lang="ar" dir="rtl">${ayah.arabic} <span class="ayah-end">${ayah.ayah}</span></p></article>`}).join('')}</section>${readerNoteDialog()}`}
function readingUnitCompanion(unit){const progress=readingUnitProgress(unit.order),saved=Number(progress.resumeAyah)||0,includes=readingUnitIncludes(unit);return `<aside class="reader-companion" aria-label="Reading Companion"><details class="reader-companion-disclosure" open><summary><span><i class="ph ph-book-open-text"></i><strong>Reading Companion</strong></span><i class="ph ph-caret-down"></i></summary><div class="reader-companion-inner"><header><p class="section-eyebrow">Reading companion</p><h2>Reading Companion</h2><p>Your place, the contents of this reading, and trusted study resources.</p></header><section class="reader-progress-card"><h3><i class="ph ph-map-pin"></i> Current Reading</h3><dl><div><dt>Journey</dt><dd>Reading Unit Journey</dd></div><div><dt>Current Unit</dt><dd>${unit.order} of ${QURAN_CANONICAL_STATUS.readingUnits}</dd></div><div><dt>Saved Place</dt><dd>${saved?esc(quranSavedPlaceLabel(unit,saved)):'Not saved yet'}</dd></div></dl></section><section><h3><i class="ph ph-list-checks"></i> About this Reading Unit</h3><p class="reader-topic-intro">This reading includes:</p><ul class="reader-topic-list">${includes.map(item=>`<li>${esc(item)}</li>`).join('')}</ul></section><details class="reader-resource-group reader-library-group" open><summary><span><i class="ph ph-books"></i> My Library</span><i class="ph ph-caret-down"></i></summary><div class="reader-library-content"><section class="reader-saved-section"><h3><i class="ph ph-star"></i> Saved Ayāt</h3>${readerSavedAyatList()}<a class="reader-saved-all-link" href="/quran/saved-ayat" data-route>Open full Saved Ayāt collection <i class="ph ph-arrow-right"></i></a></section><section class="reader-saved-section"><h3><i class="ph ph-note-pencil"></i> Personal Notes</h3>${readerNotesList()}</section></div></details><details class="reader-resource-group" open><summary><span><i class="ph ph-books"></i> Study Resources</span><i class="ph ph-caret-down"></i></summary>${Number(unit.surahNumber)===18?kahfStudyResources():`<div><a href="#" data-reader-placeholder><i class="ph ph-headphones"></i><span><strong>Audio</strong><small>Resources connected to this passage</small></span></a><a href="#" data-reader-placeholder><i class="ph ph-video"></i><span><strong>Video</strong><small>Explanations and lessons</small></span></a><a href="#" data-reader-placeholder><i class="ph ph-article"></i><span><strong>Articles</strong><small>Trusted reading resources</small></span></a></div>`}</details></div></details></aside>`}
function readingUnitResumeNotice(unit){
  const progress=readingUnitProgress(unit.order),saved=Number(progress.resumeAyah)||0;
  if(!saved)return `<aside class="reader-place-guidance"><i class="ph ph-map-pin"></i><p><strong>Save exactly where you want to resume.</strong> Select the pin beside an ayah to make it your reading place. Ummiby will not assume that a visible ayah has already been read.</p></aside>`;
  return `<aside class="reader-resume-notice"><span><i class="ph ph-map-pin-fill"></i><span><small>Your saved place</small><strong>Resume at Ayah ${saved}</strong></span></span><button type="button" class="button button-secondary" data-resume-saved-ayah="${saved}" data-resume-surah="${unit.surahNumber}">Go to Ayah ${saved}</button></aside>`;
}
function readerFrameworkFooter(unit){
  const previous=unit.order>1?unit.order-1:null,next=unit.order<QURAN_CANONICAL_STATUS.readingUnits?unit.order+1:null,completed=Boolean(readingUnitProgress(unit.order).completed);
  return `<nav class="reader-framework-footer${completed?' is-unit-complete':''}" aria-label="Reading Unit controls"><div class="reader-footer-utility reader-footer-left"><a href="/quran/reading-units" data-route><i class="ph ph-list-bullets"></i><span>Unit Index</span></a></div><div class="reader-linear-controls">${previous?`<a href="/quran/reading-unit/${previous}" data-route><i class="ph ph-caret-left"></i><span>Previous</span></a>`:'<button type="button" disabled><i class="ph ph-caret-left"></i><span>Previous</span></button>'}${completed&&next?`<a class="reader-primary-action is-next-step" href="/quran/reading-unit/${next}" data-route><span>Continue to Unit ${next}</span><i class="ph ph-arrow-right"></i></a>`:`<button class="reader-primary-action${completed?' is-complete':''}" type="button" data-complete-reading-unit="${unit.order}"><i class="ph ph-check-circle${completed?'-fill':''}"></i><span>${completed?'Completed ✓':'Mark Unit Complete'}</span></button>`}${next?`<a href="/quran/reading-unit/${next}" data-route><span>Next</span><i class="ph ph-caret-right"></i></a>`:'<button type="button" disabled><span>Next</span><i class="ph ph-caret-right"></i></button>'}</div><div class="reader-footer-utility reader-footer-right">${completed?`<button type="button" data-complete-reading-unit="${unit.order}"><i class="ph ph-arrow-counter-clockwise"></i><span>Undo Complete</span></button>`:`<button type="button" data-save-reading-place data-reading-unit="${unit.order}"><i class="ph ph-map-pin"></i><span>Save My Place</span></button>`}</div></nav>`;
}


function quranReadingSettings(prefs){return `<dialog class="reading-settings quran-reading-settings" data-reading-dialog><form method="dialog"><header><div><p class="section-eyebrow">Reading display</p><h2>Reading Preferences</h2></div><button class="dialog-close" value="close" aria-label="Close reading preferences">×</button></header><label class="range-field" for="quran-arabic-size"><span>Arabic text size</span><input id="quran-arabic-size" type="range" min="1.7" max="3.4" step="0.1" value="${prefs.arabicSize}" data-reading-size><output data-size-output>${prefs.arabicSize.toFixed(1)}rem</output></label><p class="settings-note">English remains beside the Arabic whenever the available screen width allows it.</p><button class="button button-primary" value="close">Done</button></form></dialog>`}
function studyLibraryCue(){return `<a class="study-library-cue" href="#quran-study-library"><span><i class="ph ph-books" aria-hidden="true"></i> Study resources below</span><i class="ph ph-arrow-down" aria-hidden="true"></i></a>`}
function ayatRows(){const unit=getReadingUnit(25);return readingUnitAyatRows(unit,getReadingUnitAyat(unit.order))}
function sharedStudy(count=3){return `<section class="quran-study"><div class="reader-study-heading"><span class="vision-icon"><i class="ph ph-books"></i></span><div><p class="section-eyebrow">Study Library</p><h3>Study Resources</h3><p>${count} contextual resource categories are ready for trusted links as they are added.</p></div></div><div class="study-shortcuts"><button type="button" data-reader-placeholder><i class="ph ph-headphones"></i> Audio</button><button type="button" data-reader-placeholder><i class="ph ph-video"></i> Video</button><button type="button" data-reader-placeholder><i class="ph ph-article"></i> Articles</button></div></section>`}
function quranReader(mode,unitOrder=1){const prefs=readingPreferences();if(mode==='unit'){const unit=getReadingUnit(normalizeReadingUnitOrder(unitOrder));if(!unit)return `<section class="empty-state"><h2>Reading Unit not found</h2><a href="/quran/reading-units" data-route>Return to Unit Index</a></section>`;const ayat=getReadingUnitAyat(unit.order),unitProgress=readingUnitProgress(unit.order),saved=Number(unitProgress.resumeAyah)||0;return `<section class="quran-reader reader-framework reader-framework-quran" data-quran-reading-inside data-reading-unit-reader data-reading-unit="${unit.order}" style="--reader-arabic-size:${prefs.arabicSize}rem"><header class="quran-reader-top reader-framework-top"><a class="quran-reader-exit" href="/quran" data-route aria-label="Exit Reading Mode and return to Qur’an Home"><i class="ph ph-caret-left"></i><span>Exit Reading Mode</span></a><div><span>Reading Unit ${unit.order}</span><strong>${esc(quranSurahLabel(unit.surahNumber,unit.surahName))} · ${unit.reference}</strong><div class="reader-header-progress reader-scroll-progress"><div class="progress-track" role="progressbar" aria-label="Position through this reading page" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><span data-reader-scroll-progress style="width:0%"></span></div><small data-reader-scroll-label>0% through this page</small></div></div><div class="reader-display-controls" aria-label="Arabic text size controls"><button type="button" data-arabic-size-step="-0.1" aria-label="Decrease Arabic text size">A−</button><button type="button" data-arabic-size-step="0.1" aria-label="Increase Arabic text size">A+</button>${readerInfoControl()}<button type="button" data-reading-settings aria-label="Open reading preferences"><i class="ph ph-gear-six"></i></button></div></header><div class="reader-framework-workspace">${readingUnitCompanion(unit)}<main class="reader-reading-surface">${unitProgress.completed?`<aside class="reader-completion-notice"><span><i class="ph ph-check-circle-fill"></i><span><small>Reading Unit ${unit.order}</small><strong>Completed</strong></span></span>${unit.order<QURAN_CANONICAL_STATUS.readingUnits?`<a class="button button-primary" href="/quran/reading-unit/${unit.order+1}" data-route>Continue to Unit ${unit.order+1} <i class="ph ph-arrow-right"></i></a>`:'<a class="button button-primary" href="/quran/reading-units" data-route>View completed journey</a>'}</aside>`:readingUnitResumeNotice(unit)}<header class="reader-passage-heading"><p class="section-eyebrow">Reading Unit ${unit.order}</p><h1>${esc(quranSurahLabel(unit.surahNumber,unit.surahName))}</h1><p>${esc(unit.reference)}</p></header>${readingUnitAyatRows(unit,ayat)}</main></div>${readerFrameworkFooter(unit)}${quranReadingSettings(prefs)}</section>`}const pct=18;return `<section class="quran-reader" data-quran-reading-inside style="--reader-arabic-size:${prefs.arabicSize}rem"><header class="quran-reader-top"><a class="quran-reader-exit" href="/quran" data-route><i class="ph ph-caret-left"></i><span>Exit Reading Mode</span></a><div><span>Classic Journey</span><strong>Surah 2 • Al-Baqarah, Ayah 253</strong></div><div class="reader-display-controls" aria-label="Arabic text size controls"><button type="button" data-arabic-size-step="-0.1" aria-label="Decrease Arabic text size">A−</button><button type="button" data-arabic-size-step="0.1" aria-label="Increase Arabic text size">A+</button>${readerInfoControl()}<button type="button" data-reading-settings aria-label="Open reading preferences"><i class="ph ph-gear"></i></button></div></header><section class="reader-context compact"><div><p class="section-eyebrow">Surah progress</p><h2>Surah 2 • Al-Baqarah</h2><span>Resume at Ayah 253 of 286</span></div>${progressBar(pct)}</section>${ayatRows()}${Number(unitOrder)===18?`<section class="quran-study kahf-navigator-study"><div class="reader-study-heading"><span class="vision-icon"><i class="ph ph-books"></i></span><div><p class="section-eyebrow">Study Library</p><h3>Surah Al-Kahf Study Resources</h3><p>Trusted lessons and reflections connected to Surah 18 • Al-Kahf.</p></div></div>${kahfStudyResources()}</section>`:sharedStudy()}<nav class="quran-reader-controls"><div class="reader-control-actions"><a href="#" data-reader-placeholder><i class="ph ph-caret-left"></i><span>Previous</span></a><button class="reader-center-action" type="button" data-reader-placeholder><i class="ph ph-bookmark-simple"></i><span>Save Place</span></button><a href="#" data-reader-placeholder><span>Next</span><i class="ph ph-caret-right"></i></a></div></nav>${quranReadingSettings(prefs)}</section>`}
function featuredReadings(){
  const readings=[
    {
      number:18,
      name:'Al-Kahf',
      arabic:'الكهف',
      timing:'Friday',
      icon:'sun-horizon',
      description:'Read on Friday. The Prophet ﷺ informed that the one who recites Surah Al-Kahf on Friday is granted light until the following Friday.',
      evidence:'Mishkat al-Masabih 2175 • Hasan',
      source:'https://sunnah.com/mishkat:2175',
      route:'/quran/al-kahf-friday',
      action:'Open Reader',
      artwork:'assets/images/quran/al-kahf/friday-hero.webp',
      available:true
    },
    {
      number:32,
      name:'As-Sajdah',
      arabic:'السجدة',
      timing:'Night reading',
      icon:'moon-stars',
      description:'A nightly reading connected to the Prophet’s ﷺ practice before sleep, with an additional Sunnah connection to Friday Fajr.',
      evidence:'Jamiʿ at-Tirmidhi 2892 • Sahih al-Bukhari 891',
      source:'https://sunnah.com/tirmidhi:2892',
      route:'/quran/as-sajdah',
      action:'Open Reader',
      artwork:'assets/images/quran/as-sajdah/sajdah-hero.png',
      available:true
    },
    {
      number:67,
      name:'Al-Mulk',
      arabic:'الملك',
      timing:'Night reading',
      icon:'moon-stars',
      description:'A thirty-ayah surah that intercedes for its companion until he is forgiven. It is often kept as a regular nightly reading.',
      evidence:'Jamiʿ at-Tirmidhi 2891 • Hasan',
      source:'https://sunnah.com/tirmidhi:2891',
      route:'/quran/al-mulk',
      action:'Open Reader',
      artwork:'assets/images/quran/al-mulk/mulk-hero-image.png',
      available:true
    }
  ];
  const cards=readings.map(x=>`<article class="featured-surah-card${x.available?' is-available':' is-upcoming'}${x.artwork?' has-artwork':''}"><div class="featured-surah-number" aria-hidden="true">${x.number}</div>${x.artwork?`<div class="featured-surah-card-art"><img src="${x.artwork}" alt="" loading="lazy"></div>`:''}<div class="featured-surah-card-main"><div class="featured-surah-card-heading"><span class="featured-surah-icon">${visionIcon(x.icon)}</span><div><p class="section-eyebrow">${esc(x.timing)}</p><h3>Surah ${x.number} • ${esc(x.name)}</h3><span class="featured-surah-arabic" lang="ar" dir="rtl">${x.arabic}</span></div></div><p class="featured-surah-sunnah">${esc(x.description)}</p><a class="featured-surah-evidence" href="${x.source}" target="_blank" rel="noopener noreferrer"><i class="ph ph-book-open-text" aria-hidden="true"></i><span>${esc(x.evidence)}</span><i class="ph ph-arrow-square-out" aria-hidden="true"></i></a></div><div class="featured-surah-card-action">${x.available?`<a class="button button-primary" href="${x.route}" data-route>${esc(x.action)} <i class="ph ph-arrow-right"></i></a>`:`<span class="status-pill"><i class="ph ph-clock"></i> ${esc(x.action)}</span>`}</div></article>`).join('');
  return `<section class="vision-page featured-readings-page"><div class="featured-surah-grid">${cards}</div></section>`;
}
function featuredReader(slug){const map={
 'al-kahf':['Surah 18 • Al-Kahf','Friday Reading','The People of the Cave','Ayat 9–26','It is authentically reported that whoever recites Surah al-Kahf on Friday will have a light between the two Fridays.'],
 'al-mulk':['Surah 67 • Al-Mulk','Night Reading','The Sovereignty','Ayat 1–30','A thirty-ayah surah that intercedes for its companion until he is forgiven.'],
 'as-sajdah-al-insan':['As-Sajdah & Al-Insan','Friday Fajr','Two Surahs','Structured Reading','The Prophet ﷺ recited these two surahs in the Friday Fajr prayer.'],
 'ayat-al-kursi':['Ayat al-Kursi','Al-Baqarah 2:255','The Throne Verse','One Ayah','The greatest ayah in the Book of Allah.'],
 'last-two':['Surah 2 • Al-Baqarah, Ayat 285–286','Al-Baqarah 2:285–286','Closing Ayat','Two Ayat','Whoever recites the last two ayat of Surah al-Baqarah at night, they suffice him.']};const d=map[slug]||map['al-kahf'];return `<section class="quran-reader featured-reader" data-quran-reading-inside><header class="quran-reader-top"><a href="/quran/featured-readings" data-route><i class="ph ph-caret-left"></i><span>Featured Readings</span></a><div><span>${d[1]}</span><strong>${d[0]}</strong></div><div class="reader-display-controls" aria-label="Arabic text size controls"><button type="button" data-arabic-size-step="-0.1" aria-label="Decrease Arabic text size">A−</button><button type="button" data-arabic-size-step="0.1" aria-label="Increase Arabic text size">A+</button>${readerInfoControl()}<button type="button" data-reading-settings aria-label="Open reading preferences"><i class="ph ph-gear"></i></button></div></header><section class="featured-evidence"><p class="section-eyebrow">Authentic evidence</p><h2>${d[2]}</h2><p>${d[4]}</p><small>Evidence references should be verified and linked in the canonical content data before publication.</small></section><section class="story-heading">${visionIcon('book-open-text')}<div><p class="section-eyebrow">Structured reading</p><h2>${d[2]}</h2><p>${d[3]}</p></div></section>${ayatRows()}${studyLibraryCue()}<div id="quran-study-library">${sharedStudy(5)}</div>${quranReadingSettings(readingPreferences())}</section>`}
function memorizationVision(){return `<section class="vision-page"><header class="editorial-header"><p class="page-kicker">Tracked learning</p><h2>Your memorization workspace</h2><p>Memorization remains a tracked Qur’an experience, separate from reading journey progress.</p></header><div class="vision-two-grid"><article class="metric-card"><span>Currently Memorizing</span><strong>Surah 67 • Al-Mulk</strong><p>Ayah 8 of 30</p><a href="#">Continue Memorizing</a></article><article class="metric-card"><span>Needs Revision</span><strong>3 <small>surahs</small></strong><p>Review the ayat that need attention.</p><a href="#">Open Revision</a></article></div><section class="home-section"><div class="section-heading"><div><p class="section-eyebrow">All surahs</p><h3>Surah Library</h3></div></div><div class="placeholder-panel">Existing memorization data and status tracking remain reserved for the detailed memorization implementation.</div></section></section>`}
function classicJourneyIndexPage(){const currentJuz=18;const cards=Array.from({length:30},(_,i)=>{const juz=i+1,state=juz<currentJuz?'completed':juz===currentJuz?'current':'not-started';return `<a class="classic-juz-card is-${state}" href="/quran/classic/juz/${juz}" data-route><span class="journey-tile-check"><i class="ph ph-check"></i></span><small>Classic Journey</small><strong>Juz ${juz}</strong><em>${state==='completed'?'Completed':state==='current'?'Current Juz':'Not Started'}</em></a>`}).join('');return `<section class="vision-page classic-journey-index-page"><header class="editorial-header"><p class="page-kicker">Classic Journey</p><h2>Read by Juz</h2><p>Move through the Qur’an in its familiar 30-Juz structure while Ummiby remembers your current place.</p></header><section class="journey-overview-card"><div><p class="section-eyebrow">Current Juz</p><h3>Juz ${currentJuz} of 30</h3><p>Resume at Surah 2 • Al-Baqarah, Ayah 253</p></div><div class="journey-overview-actions"><a class="button button-primary" href="/quran/classic/al-baqarah" data-route>Continue Reading</a><button class="button button-secondary" type="button" data-jump-current-juz>Jump to Current Juz</button></div></section><div class="classic-juz-grid">${cards}</div></section>`}

function readingUnitsIndexPage(){
  const journey=readingJourneyProgress(),currentOrder=journey.current,currentUnit=getReadingUnit(currentOrder),remaining=QURAN_CANONICAL_STATUS.readingUnits-journey.count;
  const tiles=QURAN_READING_LIBRARY.units.map(unit=>{const state=readingUnitState(unit.order,currentOrder),progress=readingUnitProgress(unit.order),saved=Number(progress.resumeAyah)||0;return `<article id="reading-unit-${unit.order}" class="reading-unit-tile is-${state}" data-unit-index-row data-unit-state="${state}" data-unit-order="${unit.order}" data-unit-search="${esc(`${unit.order} ${unit.id} ${unit.reference} ${unit.title} ${unit.type} ${unit.surahName}`.toLowerCase())}"><span class="journey-tile-check"><i class="ph ph-check"></i></span><div class="reading-unit-tile-heading"><small>Unit ${unit.order}</small><strong>${esc(quranSurahLabel(unit.surahNumber,unit.surahName))}</strong><span>${esc(unit.reference)}</span></div><h3>${esc(unit.title)}</h3>${saved&&!progress.completed?`<p>${esc(quranSavedPlaceLabel(unit,saved))}</p>`:''}<div class="reading-unit-tile-footer"><span class="unit-state-label">${state==='completed'?'Completed':state==='current'?'Current Unit':'Not Started'}</span><a href="/quran/reading-unit/${unit.order}" data-route>${state==='current'?'Continue':state==='completed'?'Read Again':'Open Unit'} <i class="ph ph-arrow-right"></i></a></div></article>`}).join('');
  return `<section class="vision-page reading-unit-index-page"><header class="editorial-header"><p class="page-kicker">Reading Unit Journey</p><h2>Your 294-Unit Journey</h2><p>See the complete journey at a glance, reopen any unit, and return directly to where you are now.</p></header><section class="journey-overview-card reading-unit-overview"><div><p class="section-eyebrow">Current Unit</p><h3>Unit ${currentOrder} of 294</h3><p>${currentUnit?esc(`${quranSurahLabel(currentUnit.surahNumber,currentUnit.surahName)} · ${currentUnit.reference}`):'Ready to begin'}</p><small>${journey.count} completed · ${remaining} remaining</small></div><div class="journey-overview-actions"><a class="button button-primary" href="/quran/reading-unit/${currentOrder}" data-route>Continue Reading</a><button class="button button-secondary" type="button" data-jump-current-unit><i class="ph ph-crosshair"></i> Jump to Current Unit</button></div></section><section class="reading-unit-index-toolbar"><label><i class="ph ph-magnifying-glass"></i><input type="search" placeholder="Search units, surahs, or topics" data-unit-search></label><div class="reading-unit-filter-group" aria-label="Filter Reading Units"><button class="is-active" type="button" data-unit-filter="all">All</button><button type="button" data-unit-filter="current">Current</button><button type="button" data-unit-filter="completed">Completed</button><button type="button" data-unit-filter="not-started">Remaining</button></div><span data-unit-results>294 units shown</span><button class="button button-secondary" type="button" data-open-reading-starting-point><i class="ph ph-map-pin"></i><span>Set Starting Point</span></button><button class="button button-danger-outline reading-journey-reset-button" type="button" data-open-reading-journey-reset><i class="ph ph-arrow-counter-clockwise"></i><span>Reset Journey</span></button></section><div class="reading-unit-tile-grid">${tiles}</div><dialog class="reading-journey-reset-dialog" data-reading-starting-point-dialog><form method="dialog"><header><div><p class="section-eyebrow">Reading Unit Journey</p><h2>Choose where to begin</h2></div><button class="dialog-close" value="close" aria-label="Close starting point dialog">×</button></header><p>Select the first unit you want to continue from, then choose how Ummiby should treat the earlier units.</p><label class="starting-point-field"><span>Start at Reading Unit</span><input type="number" min="1" max="294" value="${currentOrder}" data-reading-starting-unit></label><fieldset class="starting-point-options"><legend>Earlier units</legend><label><input type="radio" name="starting-point-treatment" value="complete" checked><span><strong>Mark earlier units complete</strong><small>Include them in completion totals and tracking.</small></span></label><label><input type="radio" name="starting-point-treatment" value="leave"><span><strong>Start here only</strong><small>Move your current position without marking earlier units complete.</small></span></label></fieldset><div class="reset-dialog-actions"><button class="button button-secondary" value="close">Cancel</button><button class="button button-primary" type="button" data-save-reading-starting-point>Save Starting Point</button></div></form></dialog><dialog class="reading-journey-reset-dialog" data-reading-journey-reset-dialog><form method="dialog"><header><div><p class="section-eyebrow">Reading Unit Journey</p><h2>Reset the entire journey?</h2></div><button class="dialog-close" value="close" aria-label="Close reset confirmation">×</button></header><div class="reset-dialog-warning"><i class="ph ph-warning-circle"></i><p>This permanently clears all 294 unit completions, saved places, the current unit, and Reading Unit activity history on this device.</p></div><p>Your general Qur’an reading-day record and Arabic display preferences will not be changed.</p><div class="reset-dialog-actions"><button class="button button-secondary" value="close">Cancel</button><button class="button button-danger" type="button" data-confirm-reading-journey-reset>Reset Reading Journey</button></div></form></dialog></section>`;
}

function savedAyatPage(){
  const records=savedAyatRecords().sort((a,b)=>a.surah-b.surah||a.ayah-b.ayah);
  const rows=records.map(item=>{const surah=QURAN_DATA.find(s=>s.number===item.surah),ayah=surah?.ayahs.find(a=>a.ayah===item.ayah);return `<article class="saved-ayah-row" id="saved-ayah-${item.surah}-${item.ayah}"><button class="saved-ayah-star is-saved" type="button" data-toggle-saved-ayah data-saved-surah="${item.surah}" data-saved-ayah="${item.ayah}" data-saved-surah-name="${esc(item.surahName||surah?.name||'')}" aria-label="Remove ${esc(item.surahName||surah?.name||`Surah ${item.surah}`)} Ayah ${item.ayah} from Saved Ayāt"><i class="ph-fill ph-star"></i></button><div class="saved-ayah-copy"><div class="saved-ayah-reference"><span>${item.surah}:${item.ayah}</span><strong>${esc(quranSurahLabel(item.surah,item.surahName||surah?.name||''))}</strong></div>${ayah?`<p class="saved-ayah-arabic" lang="ar" dir="rtl">${ayah.arabic} <span class="ayah-end">${item.ayah}</span></p><p class="saved-ayah-translation">${esc(ayah.translation)}</p>`:'<p class="saved-ayah-translation">Open this ayah in the reader.</p>'}</div><a class="saved-ayah-open" href="${savedAyahReaderRoute(item.surah,item.ayah)}" data-route data-open-saved-ayah="${item.surah}:${item.ayah}">Open in Reader <i class="ph ph-arrow-right"></i></a></article>`}).join('');
  return `<section class="vision-page saved-ayat-page"><header class="editorial-header"><p class="page-kicker">Your personal Qur’an collection</p><h2>Saved Ayāt</h2><p>Verses you have chosen to revisit for reflection, study, memorization, or remembrance.</p></header><section class="saved-ayat-summary"><span class="vision-icon"><i class="ph-fill ph-star"></i></span><div><strong>${records.length}</strong><span>${records.length===1?'Saved Ayah':'Saved Ayāt'}</span></div><p>Displayed in Qur’an order.</p></section>${rows?`<div class="saved-ayat-list">${rows}</div>`:`<div class="saved-ayat-empty"><i class="ph ph-star"></i><h3>Your Saved Ayāt will appear here</h3><p>Select the star beside any ayah in a Qur’an reader. Your saved collection will stay separate from your reading place.</p><a class="button button-primary" href="/quran/reading-units" data-route>Open a Reading Journey</a></div>`}</section>`;
}
function quranContent(path,quranHistoryView){if(path==='/quran/al-mulk/history')return featuredHistoryPage('mulk',quranHistoryView);if(path==='/quran/as-sajdah/history')return featuredHistoryPage('sajdah',quranHistoryView);if(path==='/quran/al-kahf-friday/history')return featuredHistoryPage('kahf',quranHistoryView);if(path==='/quran/as-sajdah')return sajdahIndex();if(/^\/quran\/as-sajdah\/section\/\d+$/.test(path))return sajdahReader(path.split('/').pop());if(path==='/quran/al-mulk')return mulkIndex();if(/^\/quran\/al-mulk\/section\/\d+$/.test(path))return mulkReader(path.split('/').pop());if(path==='/quran/al-kahf-friday')return kahfFridayIndex();if(/^\/quran\/al-kahf-friday\/section\/\d+$/.test(path))return kahfFridayReader(path.split('/').pop());if(path==='/quran')return quranHome();if(path==='/quran/journeys')return journeysPage();if(path==='/quran/navigator')return navigatorPage();if(path==='/quran/saved-ayat')return savedAyatPage();if(path==='/quran/featured-readings')return featuredReadings();if(path==='/quran/history')return readingHistoryPage(quranHistoryView);if(path==='/quran/settings')return quranSettingsPage();if(/^\/quran\/reading-unit\/\d+$/.test(path))return quranReader('unit',path.split('/').pop());if(path==='/quran/classic/al-baqarah')return quranReader('classic');if(path==='/quran/featured-readings/al-kahf')return kahfFridayIndex();if(path.startsWith('/quran/featured-readings/'))return featuredReader(path.split('/').pop());if(path.startsWith('/quran/navigator/'))return quranReader('classic',path.split('/').pop());if(path==='/quran/memorization')return memorizationVision();if(path==='/quran/reading-units')return readingUnitsIndexPage();if(path==='/quran/surahs')return classicJourneyIndexPage();if(/^\/quran\/classic\/juz\/\d+$/.test(path))return quranReader('classic');return `<section class="vision-page"><header class="editorial-header"><p class="page-kicker">Qur’an</p><h2>Page not found</h2><p>This route is not available in the current build.</p></header><div class="placeholder-panel"><a href="/quran" data-route>Return to Qur’an Home</a></div></section>`}
function ramadanHome(){return `<section class="vision-page ramadan-vision"><header class="editorial-header"><p class="page-kicker">Ramadan Central</p><h2>Keep the month close</h2><p>The Ramadan Reading Journey belongs here, alongside fasting, duaa, and the final nights.</p></header><section class="vision-feature-card ramadan-reading-card"><div>${visionIcon('book-open-text')}<div><p class="section-eyebrow">Continue Reading</p><h3>Ramadan Reading Journey</h3><p>Day 12 · Juz 12 · ʿAṣr portion</p>${progressBar(40)}</div></div><a class="button button-primary" href="/ramadan/reading" data-route>Continue</a></section><div class="vision-link-grid four"><a href="/ramadan/fasting" data-route>${visionIcon('calendar-check')}<span><strong>Fasting Tracker</strong><small>Record each day.</small></span></a><a href="/ramadan/duaa" data-route>${visionIcon('hands-praying')}<span><strong>Duaa Library</strong><small>Ramadan collections.</small></span></a><a href="#">${visionIcon('sparkle')}<span><strong>Last Ten Nights</strong><small>Nightly focus.</small></span></a><a href="/ramadan/history" data-route>${visionIcon('archive')}<span><strong>Ramadan History</strong><small>Past years.</small></span></a></div></section>`}
function ramadanReader(){return `<section class="quran-reader ramadan-reader"><header class="quran-reader-top"><a href="/ramadan" data-route><i class="ph ph-caret-left"></i></a><div><span>Ramadan Reading Journey</span><strong>Day 12 · Juz 12 · ʿAṣr Portion</strong></div><button><i class="ph ph-gear"></i></button></header><section class="reader-context compact"><div><p class="section-eyebrow">Today’s reading</p><h2>ʿAṣr Portion</h2><span>Part 4 of 5 · Day 12</span></div>${progressBar(48)}</section>${ayatRows()}${sharedStudy()}<nav class="quran-reader-controls"><a href="#"><i class="ph ph-caret-left"></i><span>Previous</span></a><button class="reader-center-action">Mark Complete</button><a href="#"><span>Next</span><i class="ph ph-caret-right"></i></a></nav></section>`}
function ramadanContent(path){if(path==='/ramadan')return ramadanHome();if(path==='/ramadan/reading')return ramadanReader();return `<section class="vision-page"><header class="editorial-header"><p class="page-kicker">Ramadan Central</p><h2>Layout placeholder</h2><p>This area remains available for the existing Ramadan blueprint.</p></header><div class="placeholder-panel"><a href="/ramadan" data-route>Return to Ramadan Home</a></div></section>`}




const NAMES_SOURCE_URL='https://abdurrahman.org/wp-content/uploads/2018/01/list-of-the-99-names-of-allaah-shaykh-uthaymeen-dawud-burbank.pdf';
function namesSaved(key){try{return JSON.parse(localStorage.getItem(key)||'[]')}catch{return[]}}
function namesFavorites(){return new Set(namesSaved('ummiby.names.favorites').map(String))}
function namesCompleted(){return new Set(namesSaved('ummiby.names.completed').map(String))}
function namesBreadcrumb(items=[]){return `<nav class="names-breadcrumb" aria-label="Breadcrumb"><a href="/names" data-route>Names of Allah</a>${items.map((x,i)=>`<i class="ph ph-caret-right" aria-hidden="true"></i>${i===items.length-1?`<span aria-current="page">${esc(x.label)}</span>`:`<a href="${x.route}" data-route>${esc(x.label)}</a>`}`).join('')}</nav>`}
function namesEpigraph(){return pageEpigraph({quote:'“And to Allah belong the best names, so invoke Him by them.”',citation:'Qur’an 7:180'});}
function namesCard(x,{compact=false}={}){const fav=namesFavorites().has(x.id),done=namesCompleted().has(x.id);return `<article class="name-card${compact?' is-compact':''}" data-name-card data-name-search="${esc(`${x.transliteration} ${x.arabic} ${x.meaning}`.toLowerCase())}" data-name-source="${x.source.toLowerCase()}"><a href="/names/name/${x.id}" data-route><span class="name-number">${String(x.order).padStart(2,'0')}</span><span class="name-arabic" lang="ar" dir="rtl">${x.arabic}</span><span class="name-transliteration">${esc(x.transliteration)}</span><span class="name-meaning">${esc(x.meaning)}</span><span class="name-source">${esc(x.source)}</span>${done?'<span class="name-complete-mark"><i class="ph ph-check-circle"></i> Studied</span>':''}</a><button class="name-favorite-button${fav?' is-active':''}" type="button" data-name-favorite="${x.id}" aria-label="${fav?'Remove from':'Add to'} favorites" aria-pressed="${fav}"><i class="ph ph-heart${fav?'-fill':''}"></i></button></article>`}
function namesHome(){const completed=namesCompleted(),current=NAMES_OF_ALLAH.find(x=>!completed.has(x.id))||NAMES_OF_ALLAH[0],featured=NAMES_OF_ALLAH[29],percent=Math.round(completed.size/NAMES_OF_ALLAH.length*100);return `<section class="vision-page names-page names-home">${namesEpigraph()}<div class="names-home-grid"><section class="names-continue-card"><p class="section-eyebrow">Continue learning</p><div class="names-featured-arabic" lang="ar" dir="rtl">${current.arabic}</div><h2>${esc(current.transliteration)}</h2><p>${esc(current.meaning)}</p><div class="mini-progress"><span style="width:${percent}%"></span></div><small>${completed.size} of ${NAMES_OF_ALLAH.length} studied</small><a class="button button-primary" href="/names/name/${current.id}" data-route>Continue with Name ${current.order} <i class="ph ph-arrow-right"></i></a></section><aside class="names-progress-card"><span class="names-progress-ring" style="--progress:${percent}%"><strong>${percent}%</strong></span><div><p class="section-eyebrow">Your journey</p><h2>Learning Progress</h2><p>A quiet place to learn, revisit, and reflect upon each Beautiful Name.</p><a href="/names/review" data-route>Open review →</a></div></aside></div><section class="names-home-section"><header><div><p class="section-eyebrow">Begin here</p><h2>Explore the companion</h2></div></header><div class="names-action-grid">${[['/names/explore','Explore the Names','Browse the complete collection with search and source filters.','magnifying-glass'],['/names/learn','Learning Journey','Move through the Names in a simple, guided sequence.','path'],['/names/learned','Learned Names','Watch the collection fill with color as you learn each Name.','seal-check'],['/names/review','Review & Reflection','Return to studied Names and prepare for future review tools.','arrows-clockwise'],['/names/favorites','Favorites','Keep the Names you want to revisit close at hand.','heart'],['/names/about','About This Collection','Read the list source and the foundation for this module.','info']].map(x=>`<a class="names-action-card" href="${x[0]}" data-route><i class="ph ph-${x[3]}"></i><span><strong>${x[1]}</strong><small>${x[2]}</small></span><i class="ph ph-caret-right"></i></a>`).join('')}</div></section><section class="names-home-section"><header><div><p class="section-eyebrow">Featured Name</p><h2>A Name to revisit</h2></div><a href="/names/explore" data-route>View all Names →</a></header>${namesCard(featured,{compact:true})}</section></section>`}
function namesExplore(){return `<section class="vision-page names-page">${namesBreadcrumb([{label:'Explore'}])}${namesEpigraph()}<header class="names-section-heading"><p class="section-eyebrow">The complete collection</p><h2>The Beautiful Names of Allah</h2><p>Search the 99 Names in this collection and filter by whether the Name is listed from the Qur’an or authentic Sunnah.</p></header><div class="names-toolbar"><label><i class="ph ph-magnifying-glass"></i><input type="search" placeholder="Search Arabic, transliteration, or meaning" data-names-search></label><div class="names-filter-group"><button class="is-active" data-names-filter="all">All 99</button><button data-names-filter="qur’an">Qur’an · 81</button><button data-names-filter="sunnah">Sunnah · 18</button></div><span data-names-results>99 Names shown</span></div><div class="names-library-grid">${NAMES_OF_ALLAH.map(x=>namesCard(x)).join('')}</div><div class="names-empty" data-names-empty hidden><i class="ph ph-magnifying-glass"></i><h3>No Names found</h3><p>Try a different search or source filter.</p></div></section>`}
function namesDetail(id){const x=nameById(id)||NAMES_OF_ALLAH[0],prev=NAMES_OF_ALLAH[x.order-2],next=NAMES_OF_ALLAH[x.order],fav=namesFavorites().has(x.id),done=namesCompleted().has(x.id);return `<section class="vision-page names-page names-detail">${namesBreadcrumb([{label:'Explore',route:'/names/explore'},{label:x.transliteration}])}<article class="name-hero-card"><span class="name-number">${String(x.order).padStart(2,'0')}</span><button class="name-favorite-button is-hero${fav?' is-active':''}" type="button" data-name-favorite="${x.id}" aria-pressed="${fav}"><i class="ph ph-heart${fav?'-fill':''}"></i><span>${fav?'Favorited':'Favorite'}</span></button><div class="name-hero-arabic" lang="ar" dir="rtl">${x.arabic}</div><p class="section-eyebrow">${esc(x.source)} source</p><h2>${esc(x.transliteration)}</h2><p class="name-hero-meaning">${esc(x.meaning)}</p></article><div class="name-detail-sections">${[['Explanation','A sourced explanation of this Beautiful Name will be added in a future content phase.','book-open-text'],['Evidence','Qur’anic verses or authentic hadith evidence will be placed here.','quotes'],['Reflection','Guided reflection and practical effects upon worship will live here.','sparkle'],['Related Names','Connections with other Beautiful Names will be developed here.','circles-three-plus'],['Study Resources','Verified audio, video, and reading resources will be gathered here.','books']].map(x=>`<article><i class="ph ph-${x[2]}"></i><div><h3>${x[0]}</h3><p>${x[1]}</p><span class="status-pill">Content coming later</span></div></article>`).join('')}</div><div class="names-detail-actions"><a class="button button-secondary${prev?'':' is-disabled'}" href="${prev?`/names/name/${prev.id}`:'#'}" ${prev?'data-route':''}><i class="ph ph-arrow-left"></i> ${prev?esc(prev.transliteration):'Previous'}</a><button class="button ${done?'button-secondary is-done':'button-primary'}" type="button" data-name-complete="${x.id}">${done?'<i class="ph ph-check"></i> Studied':'Mark as Studied'}</button><a class="button button-secondary${next?'':' is-disabled'}" href="${next?`/names/name/${next.id}`:'#'}" ${next?'data-route':''}>${next?esc(next.transliteration):'Next'} <i class="ph ph-arrow-right"></i></a></div></section>`}
function namesLearn(){const completed=namesCompleted(),current=NAMES_OF_ALLAH.find(x=>!completed.has(x.id))||NAMES_OF_ALLAH[0];return `<section class="vision-page names-page">${namesBreadcrumb([{label:'Learning Journey'}])}${namesEpigraph()}<header class="names-section-heading"><p class="section-eyebrow">A guided path</p><h2>Learning Journey</h2><p>Move through the collection one Name at a time. This foundation tracks studied Names now and leaves room for richer lessons later.</p></header><article class="names-journey-card"><div><span class="name-number">${String(current.order).padStart(2,'0')}</span><p class="section-eyebrow">Continue your journey</p><h2>${esc(current.transliteration)}</h2><p class="name-arabic" lang="ar" dir="rtl">${current.arabic}</p><p>${esc(current.meaning)}</p><a class="button button-primary" href="/names/name/${current.id}" data-route>Open this Name <i class="ph ph-arrow-right"></i></a></div><aside><strong>${completed.size}</strong><span>Names studied</span><div class="mini-progress"><span style="width:${Math.round(completed.size/99*100)}%"></span></div><small>${99-completed.size} remaining</small></aside></article><div class="names-stage-grid">${[['Names 1–20','Foundational sequence','1'],['Names 21–40','Continue the collection','21'],['Names 41–60','Majesty, knowledge, and power','41'],['Names 61–81','Complete the Qur’anic Names','61'],['Names 82–99','Names established in the Sunnah','82']].map(x=>`<a href="/names/name/${x[2]}" data-route><span>${x[0]}</span><strong>${x[1]}</strong><i class="ph ph-arrow-right"></i></a>`).join('')}</div></section>`}
function namesLearned(){const completed=namesCompleted(),learned=NAMES_OF_ALLAH.filter(x=>completed.has(x.id)),percent=Math.round(learned.length/NAMES_OF_ALLAH.length*100);return `<section class="vision-page names-page names-learned-page">${namesBreadcrumb([{label:'Learned Names'}])}${namesEpigraph()}<header class="names-section-heading"><p class="section-eyebrow">Your learning record</p><h2>My Learned Names</h2><p>Mark each Name as learned and watch the collection gradually fill with the lapis color of this companion.</p></header><div class="memorization-summary names-learned-summary"><article><span>Beautiful Names</span><strong>${NAMES_OF_ALLAH.length}</strong></article><article><span>Learned</span><strong>${learned.length}</strong></article><article><span>Still learning</span><strong>${NAMES_OF_ALLAH.length-learned.length}</strong></article><article><span>Progress</span><strong>${percent}%</strong></article></div><section class="memorization-collection names-learned-collection"><header><div><p class="section-eyebrow">The complete collection</p><h3>${learned.length} of ${NAMES_OF_ALLAH.length} learned</h3></div><span>${percent}%</span></header><div class="memorization-progress"><span style="width:${percent}%"></span></div><div class="duaa-badge-grid names-learned-grid">${NAMES_OF_ALLAH.map(x=>{const isLearned=completed.has(x.id);return `<article class="duaa-memory-badge name-learning-badge${isLearned?' is-memorized':''}"><a href="/names/name/${x.id}" data-route aria-label="Open ${esc(x.transliteration)}"><span class="badge-number">${x.order}</span><i class="ph ph-seal-check" aria-hidden="true"></i><span class="name-learning-arabic" lang="ar" dir="rtl">${x.arabic}</span><strong>${esc(x.transliteration)}</strong><small>${esc(x.meaning)}</small></a><button type="button" data-name-learned="${x.id}" aria-pressed="${isLearned}">${isLearned?'Learned':'Mark learned'}</button></article>`}).join('')}</div></section></section>`}
function namesReview(){const done=NAMES_OF_ALLAH.filter(x=>namesCompleted().has(x.id));return `<section class="vision-page names-page">${namesBreadcrumb([{label:'Review & Reflection'}])}${namesEpigraph()}<header class="names-section-heading"><p class="section-eyebrow">Return and remember</p><h2>Review & Reflection</h2><p>Your studied Names appear here. Future versions can add spaced review, prompts, notes, and knowledge checks without changing this foundation.</p></header>${done.length?`<div class="names-library-grid">${done.map(x=>namesCard(x,{compact:true})).join('')}</div>`:`<div class="names-empty is-panel"><i class="ph ph-arrows-clockwise"></i><h3>Your review space is ready</h3><p>Mark a Name as studied and it will appear here for review.</p><a class="button button-primary" href="/names/learn" data-route>Begin learning</a></div>`}</section>`}
function namesFavoritesPage(){const fav=NAMES_OF_ALLAH.filter(x=>namesFavorites().has(x.id));return `<section class="vision-page names-page">${namesBreadcrumb([{label:'Favorites'}])}${namesEpigraph()}<header class="names-section-heading"><p class="section-eyebrow">Saved for return</p><h2>Favorite Names</h2><p>Keep meaningful Names close for study and reflection.</p></header>${fav.length?`<div class="names-library-grid">${fav.map(x=>namesCard(x,{compact:true})).join('')}</div>`:`<div class="names-empty is-panel"><i class="ph ph-heart"></i><h3>No favorites yet</h3><p>Select the heart on any Name to save it here.</p><a class="button button-primary" href="/names/explore" data-route>Explore the Names</a></div>`}</section>`}
function namesAbout(){return `<section class="vision-page names-page">${namesBreadcrumb([{label:'About This Collection'}])}${namesEpigraph()}<header class="names-section-heading"><p class="section-eyebrow">Source and methodology</p><h2>About This Collection</h2><p>This foundation begins with a clearly identified scholarly list while leaving room for future sourced explanations and careful content review.</p></header><article class="names-source-card"><i class="ph ph-book-open-text"></i><div><p class="section-eyebrow">List source</p><h3>The Ninety-Nine Names of Allah</h3><p>Based on Shaykh Muḥammad ibn Ṣāliḥ al-‘Uthaymīn’s <em>Al-Qawā‘id al-Muthlā</em>, translated by Dawud Burbank. The source lists 81 Names extracted from the Qur’an and 18 Names extracted from the authentic Sunnah.</p><a class="button button-secondary" href="${NAMES_SOURCE_URL}" target="_blank" rel="noopener noreferrer">Open source PDF <i class="ph ph-arrow-square-out"></i></a></div></article><div class="names-about-grid"><article><i class="ph ph-check-circle"></i><h3>Current foundation</h3><p>Each record includes the Arabic Name, transliteration, concise English meaning, and Qur’an or Sunnah source category.</p></article><article><i class="ph ph-books"></i><h3>Future content</h3><p>Explanations, evidence, reflections, related Names, and resources will be added only as they are carefully sourced and reviewed.</p></article><article><i class="ph ph-database"></i><h3>Expandable structure</h3><p>The module can grow without redesigning its routes, library, favorites, journey, or review experience.</p></article></div></section>`}
function namesContent(path){const p=routeParts(path);if(path==='/names')return namesHome();if(path==='/names/explore'||path==='/names/all')return namesExplore();if(path==='/names/learn'||path==='/names/study')return namesLearn();if(path==='/names/learned')return namesLearned();if(path==='/names/review')return namesReview();if(path==='/names/favorites')return namesFavoritesPage();if(path==='/names/about')return namesAbout();if(p[1]==='name'&&p[2])return namesDetail(p[2]);return namesHome();}

