function prayerBreadcrumb(items=[]){return `<nav class="prayer-breadcrumb" aria-label="Breadcrumb"><a href="/prayer" data-route>Prayer Companion</a>${items.map((x,i)=>`<i class="ph ph-caret-right" aria-hidden="true"></i>${i===items.length-1?`<span aria-current="page">${esc(x.label)}</span>`:`<a href="${x.route}" data-route>${esc(x.label)}</a>`}`).join('')}</nav>`}
function prayerEpigraph(){return pageEpigraph({quote:'“Indeed, prayer has been decreed upon the believers at specified times.”',citation:'Qur’an 4:103'});}
function prayerCard(route,title,description,icon='arrow-right'){return `<a class="prayer-companion-card" href="${route}" data-route><span class="prayer-card-icon"><i class="ph ph-${icon}" aria-hidden="true"></i></span><span><strong>${esc(title)}</strong><small>${esc(description)}</small></span><i class="ph ph-caret-right" aria-hidden="true"></i></a>`}
function prayerSectionHeader(eyebrow,title,description=''){return `<header class="prayer-section-heading"><p class="section-eyebrow">${esc(eyebrow)}</p><h2>${esc(title)}</h2>${description?`<p>${esc(description)}</p>`:''}</header>`}
function prayerHome(){
 const guides=[['/prayer/daily-prayers','Five Daily Prayers','Study Fajr, Dhuhr, Asr, Maghrib, and Isha.','clock-countdown'],['/prayer/sunnah','Sunnah & Voluntary Prayers','Explore Rawatib, Duha, Witr, night prayer, and more.','sparkle'],['/prayer/learn','Learn the Prayer','Move step by step from preparation through tasleem.','student'],['/prayer/wudu','Wudu Companion','Learn purification through a guided framework.','drop'],['/prayer/duaa','Prayer Duaa Library','Browse supplications by their place within the prayer.','hands-praying'],['/prayer/knowledge','Prayer Knowledge','Study conditions, pillars, khushu’, congregation, travel, and more.','books'],['/prayer/progress','My Progress','See the learning areas that will eventually track your mastery.','chart-donut']];
 const times=[['Fajr','4:42 AM'],['Sunrise','6:05 AM'],['Dhuhr','12:34 PM'],['Asr','4:08 PM'],['Maghrib','7:02 PM'],['Isha','8:25 PM']];
 return `<section class="vision-page prayer-companion-page prayer-home">${prayerEpigraph()}<div class="prayer-home-grid"><section><div class="prayer-guided-intro"><span><i class="ph ph-path"></i></span><div><p class="section-eyebrow">Your guided path</p><h2>Where would you like to begin?</h2><p>Move between practical learning, prayer-specific study, supplications, and steady progress without leaving the companion.</p></div></div><div class="prayer-home-links">${guides.map(x=>prayerCard(...x)).join('')}</div></section><aside class="prayer-today-panel"><header><div><p class="section-eyebrow">Today</p><h2>Prayer Times</h2></div><span class="status-pill">Placeholder</span></header><p class="prayer-location"><i class="ph ph-map-pin"></i> Local prayer times will appear here</p><div class="prayer-time-list">${times.map(([name,time],i)=>`<div${i===3?' class="is-next"':''}><span>${name}${i===3?'<small>Next prayer</small>':''}</span><strong>${time}</strong></div>`).join('')}</div><div class="prayer-side-links">${prayerCard('/prayer/calendar','Prayer Calendar','View a future day, month, or prayer schedule.','calendar-dots')}${prayerCard('/prayer/settings','Prayer Settings','Calculation method, location, and notification controls.','sliders-horizontal')}</div></aside></div></section>`;
}
function prayerDailyIndex(){return `<section class="vision-page prayer-companion-page">${prayerBreadcrumb([{label:'Five Daily Prayers'}])}${prayerEpigraph()}${prayerSectionHeader('Study each prayer','Five Daily Prayers','Open a prayer to see its core details and the complete future study framework.')}<div class="prayer-feature-grid">${Object.entries(PRAYER_DAILY).map(([id,x])=>prayerCard(`/prayer/daily-prayers/${id}`,x.name,`${x.subtitle} · ${x.rakaa} · ${x.recitation}`,x.icon)).join('')}</div></section>`}
function prayerDailyDetail(id){const x=PRAYER_DAILY[id]||PRAYER_DAILY.fajr;const sections=[['Overview','A concise introduction to this prayer and its place in the day.','book-open'],['How to Pray','A future guided walkthrough specific to this prayer.','steps'],['Related Duaa','Canonical supplications connected to this prayer.','hands-praying'],['Virtues','Authentic evidences concerning its virtues and importance.','seal-check'],['Study Library','Audio, video, article, and reference resources.','books']];return `<section class="vision-page prayer-companion-page">${prayerBreadcrumb([{label:'Five Daily Prayers',route:'/prayer/daily-prayers'},{label:x.name}])}${pageEpigraph({quote:'“The first matter that the servant will be brought to account for on the Day of Resurrection is the prayer.”',citation:'Prophetic hadith — source verification and full citation reserved for content phase'})}<article class="prayer-summary-card"><header><span class="prayer-card-icon is-large"><i class="ph ph-${x.icon}"></i></span><div><p class="section-eyebrow">${esc(x.subtitle)}</p><h2>${esc(x.name)} Prayer</h2></div></header><div>${[['Rak‘ah',x.rakaa],['Recitation',x.recitation],['Beginning time',x.beginning],['Ending time',x.ending]].map(([k,v])=>`<section><span>${esc(k)}</span><strong>${esc(v)}</strong></section>`).join('')}</div><p class="placeholder-note"><i class="ph ph-info"></i> Timing descriptions are structural placeholders and will receive sourced fiqh detail in a future content phase.</p></article><div class="prayer-structure-list">${sections.map(([title,desc,icon])=>`<article><span class="prayer-card-icon"><i class="ph ph-${icon}"></i></span><div><h3>${title}</h3><p>${desc}</p><span class="status-pill">Content coming in a future version</span></div></article>`).join('')}</div></section>`}
function prayerCollectionPage(kind,title,data,base,description){return `<section class="vision-page prayer-companion-page">${prayerBreadcrumb([{label:title}])}${prayerEpigraph()}${prayerSectionHeader('Guided learning',title,description)}<div class="prayer-feature-grid">${Object.entries(data).map(([id,x])=>prayerCard(`${base}/${id}`,x[0],x[1],x[2]||'arrow-right')).join('')}</div></section>`}
function prayerPlaceholderDetail(parentRoute,parentLabel,title,description,icon='book-open-text'){return `<section class="vision-page prayer-companion-page">${prayerBreadcrumb([{label:parentLabel,route:parentRoute},{label:title}])}<article class="prayer-placeholder-shell"><span class="prayer-card-icon is-large"><i class="ph ph-${icon}"></i></span><p class="section-eyebrow">Framework established</p><h2>${esc(title)}</h2><p>${esc(description)}</p><div class="prayer-future-slots"><div><i class="ph ph-book-open-text"></i><strong>Guided content</strong><small>Structured lessons and sourced explanations will live here.</small></div><div><i class="ph ph-list-checks"></i><strong>Completion</strong><small>This page is ready for future completion and mastery tracking.</small></div><div><i class="ph ph-books"></i><strong>Study resources</strong><small>Canonical references and library resources can plug in without changing the route.</small></div></div><a class="button button-secondary" href="${parentRoute}" data-route><i class="ph ph-arrow-left"></i> Back to ${esc(parentLabel)}</a></article></section>`}
function prayerDuaaIndex(){return `<section class="vision-page prayer-companion-page">${prayerBreadcrumb([{label:'Prayer Duaa Library'}])}${prayerEpigraph()}${prayerSectionHeader('Shared canonical records','Prayer Duaa Library','The collection routes are established now. Future native Read and Learn modes will reuse the canonical Duaa records without duplicating data.')}<aside class="prayer-architecture-note"><i class="ph ph-database"></i><div><strong>One source of truth</strong><p>Prayer Companion will reference shared supplication records while keeping its own module-native reading.</p></div></aside><div class="prayer-feature-grid">${Object.entries(PRAYER_DUAA).map(([id,x])=>prayerCard(`/prayer/duaa/${id}`,x[0],x[1],'hands-praying')).join('')}</div></section>`}
function prayerProgress(){const areas=[['Prayer Lessons','0 of 11','0%','student'],['Prayer Duaa','0 collections','0%','hands-praying'],['Wudu','0 of 6','0%','drop'],['Overall Progress','Foundation ready','0%','chart-donut']];return `<section class="vision-page prayer-companion-page">${prayerBreadcrumb([{label:'My Progress'}])}${prayerEpigraph()}${prayerSectionHeader('Your learning journey','My Progress','Future versions will connect lesson completion, memorization, wudu learning, and mastery tracking here.')}<div class="prayer-progress-grid">${areas.map(([title,value,pct,icon])=>`<article><span class="prayer-card-icon"><i class="ph ph-${icon}"></i></span><div><span>${title}</span><strong>${value}</strong></div><div class="mini-progress"><span style="width:${pct}"></span></div><small>${pct} complete · Placeholder</small></article>`).join('')}</div><aside class="prayer-progress-roadmap"><i class="ph ph-path"></i><div><h3>A companion that grows with you</h3><p>This dashboard is prepared for lesson completion, shared duaa memorization status, wudu completion, and overall mastery—without implementing tracking prematurely.</p></div></aside></section>`}
function prayerContent(path){const p=routeParts(path);if(path==='/prayer')return prayerHome();if(path==='/prayer/daily-prayers')return prayerDailyIndex();if(p[1]==='daily-prayers'&&p[2])return prayerDailyDetail(p[2]);if(path==='/prayer/sunnah')return prayerCollectionPage('sunnah','Sunnah & Voluntary Prayers',PRAYER_SUNNAH,'/prayer/sunnah','Explore the prayers offered beyond the five obligatory prayers.');if(p[1]==='sunnah'&&p[2]){const x=PRAYER_SUNNAH[p[2]]||['Prayer','Placeholder prayer page.','sparkle'];return prayerPlaceholderDetail('/prayer/sunnah','Sunnah & Voluntary Prayers',x[0],x[1],x[2]);}if(path==='/prayer/learn')return prayerCollectionPage('learn','Learn the Prayer',PRAYER_LESSONS,'/prayer/learn','Follow the prayer in order, one clear lesson at a time.');if(p[1]==='learn'&&p[2]){const x=PRAYER_LESSONS[p[2]]||['Prayer Lesson','Placeholder lesson.','student'];return prayerPlaceholderDetail('/prayer/learn','Learn the Prayer',x[0],x[1],x[2]);}if(path==='/prayer/wudu')return prayerCollectionPage('wudu','Wudu Companion',PRAYER_WUDU,'/prayer/wudu','Learn purification through a practical and ordered framework.');if(p[1]==='wudu'&&p[2]){const x=PRAYER_WUDU[p[2]]||['Wudu Topic','Placeholder topic.','drop'];return prayerPlaceholderDetail('/prayer/wudu','Wudu Companion',x[0],x[1],x[2]);}if(path==='/prayer/knowledge')return prayerCollectionPage('knowledge','Prayer Knowledge',PRAYER_KNOWLEDGE,'/prayer/knowledge','Build the knowledge that supports a sound, attentive prayer.');if(p[1]==='knowledge'&&p[2]){const x=PRAYER_KNOWLEDGE[p[2]]||['Prayer Topic','Placeholder topic.','books'];return prayerPlaceholderDetail('/prayer/knowledge','Prayer Knowledge',x[0],x[1],x[2]);}if(path==='/prayer/duaa')return prayerDuaaIndex();if(p[1]==='duaa'&&p[2]){const x=PRAYER_DUAA[p[2]]||['Prayer Duaa','Canonical supplication collection shell.'];return prayerPlaceholderDetail('/prayer/duaa','Prayer Duaa Library',x[0],`${x[1]} This shell is reserved for the future native Prayer Read Mode and Learn Mode.`,'hands-praying');}if(path==='/prayer/progress')return prayerProgress();if(path==='/prayer/calendar')return prayerPlaceholderDetail('/prayer','Prayer Home','Prayer Calendar','A future calendar for daily and monthly prayer schedules.','calendar-dots');if(path==='/prayer/settings')return prayerPlaceholderDetail('/prayer','Prayer Home','Prayer Settings','Future controls for location, calculation method, adjustments, and notifications.','sliders-horizontal');return prayerHome();}

function futureModulePlaceholder(active){
  const isPrayer=active.id==='prayer';
  const features=isPrayer
    ? [
        ['book-open-text','Prayer from beginning to end','A future guided resource covering preparation, movements, recitations, and completion of the prayer.'],
        ['books','Trusted study resources','Articles, lessons, and references will be gathered into one calm study library.'],
        ['clock','Prayer times','A future location-aware prayer-time area can live here without crowding the learning resources.']
      ]
    : [
        ['calendar-check','Year-round fasting record','A future place to record obligatory, make-up, and voluntary fasts beyond Ramadan.'],
        ['book-open-text','Authentic fasting guidance','Trusted resources about intentions, rulings, virtues, and common questions.'],
        ['archive','Fasting history','A clear long-term record while Ramadan-specific tracking remains in Ramadan Central.']
      ];
  return `<section class="vision-page future-module-placeholder"><header class="editorial-header"><p class="page-kicker">${esc(active.label)}</p><h2>${esc(active.bannerTitle)}</h2><p>${esc(active.description)}</p><span class="status-pill">Placeholder module</span></header><div class="vision-link-grid three">${features.map(([iconName,title,description])=>`<article class="future-module-feature">${visionIcon(iconName)}<span><strong>${esc(title)}</strong><small>${esc(description)}</small></span></article>`).join('')}</div><div class="placeholder-panel"><p>This module is registered in the global navigation and ready for its future blueprint. No tracking or live location services have been enabled yet.</p></div></section>`;
}

function placeholders(active){if(active.id==='home')return sidebarOrder.filter(id=>!['home','settings','prayer','fasting'].includes(id)).map(id=>{const x=modules[id];return `<article class="card"><span class="status-pill">Foundation registered</span><h2>${esc(x.label)}</h2><p>${esc(x.description)}</p><a href="${x.navigation[0].route}" data-route>Open ${esc(x.label)}</a></article>`}).join('');return `<article class="card"><span class="status-pill">v${APP_VERSION} foundation</span><h2>Module shell is ready</h2><p>This module remains a placeholder while Duaa receives its first complete collection and reading.</p></article>`}
function bannerMeta(active,path){
  if(path==='/quran/featured-readings')return {eyebrow:'QUR’AN',title:'Featured Readings',description:'Return to surahs connected to established times and practices from the Sunnah.'};
  if(path==='/quran/al-kahf-friday')return {eyebrow:'QUR’AN',title:'Surah 18 • Al-Kahf',description:'Return each Friday to read Surah Al-Kahf in eight guided sections.'};
  if(path==='/quran/al-mulk')return {eyebrow:'QUR’AN',title:'Surah 67 • Al-Mulk',description:'Return nightly to read Surah Al-Mulk in four guided sections.'};
  if(path==='/quran/as-sajdah')return {eyebrow:'QUR’AN',title:'Surah 32 • As-Sajdah',description:'Return nightly to read Surah As-Sajdah in four guided sections.'};
  if(path==='/quran/journeys'||path==='/quran/reading-units'||path==='/quran/surahs')return {eyebrow:'Qur’an',title:'Your Reading Journeys',description:'Continue your journey through the Qur’an with a reading path that remembers your progress and grows with you over time.'};
  const duaaBanners={
    '/duaa':{eyebrow:'DUAA',title:'Duaa Home',description:'Authentic supplications for every stage of your day.'},
    '/duaa/morning':{eyebrow:'DUAA',title:'Morning Duaas',description:'Begin your day with authentic remembrance.'},
    '/duaa/evening':{eyebrow:'DUAA',title:'Evening Duaas',description:'Close your day with authentic remembrance.'},
    '/duaa/sleep':{eyebrow:'DUAA',title:'Before Sleep Duaas',description:'End your day with remembrance, protection, and trust in Allah.'},
    '/duaa/travel':{eyebrow:'DUAA',title:'Travel Duaas',description:'Remember Allah as you set out, travel, stop, and return.'},
    '/duaa/weather':{eyebrow:'DUAA',title:'Weather Duaas',description:'Remember Allah through rain, wind, storms, and changing skies.'},
    '/duaa/prayer':{eyebrow:'DUAA',title:'Prayer Duaas',description:'Supplications connected to the masjid, prayer, and seeking guidance.'},
    '/duaa/collections':{eyebrow:'DUAA',title:'Collections',description:'Explore authentic supplications for every time and situation.'},
    '/duaa/memorization':{eyebrow:'DUAA',title:'My Duaa Memorization',description:'See every supplication you have memorized and what you are still learning.'},
    '/duaa/history':{eyebrow:'DUAA',title:'History',description:'Reflect on your journey of remembrance.'},
    '/duaa/food':{eyebrow:'DUAA',title:'Food & Drink Duaas',description:'Remember Allah before, during, and after eating and drinking.'},
    '/duaa/clothing':{eyebrow:'DUAA',title:'Clothing Duaas',description:'Remember Allah when dressing and receiving new clothing.'},
    '/duaa/anxiety':{eyebrow:'DUAA',title:'Anxiety & Sadness Duaas',description:'Turn to Allah through worry, grief, distress, and sadness.'},
    '/duaa/quranic':{eyebrow:'DUAA',title:'Qur’anic Duaas',description:'Supplications from the Qur’an, including the prayers of the prophets and the righteous.'}
  };
  if(active.id==='prayer'){const titles={'daily-prayers':['Five Daily Prayers','Study each obligatory prayer with clarity and structure.'],sunnah:['Sunnah & Voluntary Prayers','Explore the prayers that surround and enrich the obligatory prayers.'],learn:['Learn the Prayer','Move through the prayer from preparation to completion.'],wudu:['Wudu Companion','Learn purification as a guided foundation for prayer.'],duaa:['Prayer Duaa Library','Find supplications by their place within the prayer.'],knowledge:['Prayer Knowledge','Build sound understanding around the prayer.'],progress:['My Progress','See the learning path that will grow with you.'],calendar:['Prayer Calendar','A future home for prayer schedules.'],settings:['Prayer Settings','Future controls for accurate local prayer times.']};const key=routeParts(path)[1];const meta=titles[key];return {eyebrow:'PRAYER COMPANION',title:meta?.[0]||active.bannerTitle,description:meta?.[1]||active.description};}
  return duaaBanners[path]||{eyebrow:active.bannerEyebrow,title:active.bannerTitle,description:active.description};
}
function viewName(active,path){if(active.id==='names'){const p=routeParts(path);if(p[1]==='name'&&p[2])return nameById(p[2])?.transliteration||'Beautiful Name';}if(active.id==='prayer'){const p=routeParts(path);if(p.length>2)return (PRAYER_DAILY[p[2]]?.name||PRAYER_SUNNAH[p[2]]?.[0]||PRAYER_LESSONS[p[2]]?.[0]||PRAYER_WUDU[p[2]]?.[0]||PRAYER_KNOWLEDGE[p[2]]?.[0]||PRAYER_DUAA[p[2]]?.[0]||'Prayer Companion');}if(active.id==='duaa'){if(path==='/duaa/memorization')return'My Duaa Memorization';const p=routeParts(path),c=duaaCollections[p[1]];if(p[2]==='read')return c?.label||'Reading';if(c)return c.label;if(path==='/duaa/collections')return'Collections';if(path==='/duaa/history')return'History';}if(active.id==='quran'){if(path==='/quran/journeys'||path==='/quran/reading-units'||path==='/quran/surahs')return'Reading Journeys';if(path.includes('/reading-unit/'))return'Reading Unit';if(path.includes('/classic/'))return'Classic Journey';if(path.includes('/al-mulk'))return'Surah Al-Mulk';if(path.includes('/al-kahf-friday'))return'Al-Kahf Friday';if(path.includes('/featured-readings/'))return'Featured Reading';if(path==='/quran/saved-ayat')return'Saved Ayāt';if(path.includes('/navigator'))return'Qur’an Navigator';}if(active.id==='ramadan'&&path==='/ramadan/reading')return'Ramadan Reading Journey';return active.navigation.find(x=>x.route===path)?.label||active.navigation[0].label}
function accountName(identity,user){return identity?.fullName||user?.user_metadata?.full_name||user?.user_metadata?.name||user?.email?.split('@')[0]||'My Account'}
function accountInitials(name,email){const source=String(name||email||'U').trim();const words=source.split(/\s+/).filter(Boolean);return esc((words.length>1?`${words[0][0]}${words.at(-1)[0]}`:source.slice(0,2)).toUpperCase())}
function formatAccountDate(value){if(!value)return 'Not available';const date=new Date(value);return Number.isNaN(date.getTime())?'Not available':date.toLocaleString([], {dateStyle:'medium',timeStyle:'short'})}
function accountControls(user,identity,configured){
  const isAuthenticated=Boolean(user);
  const name=isAuthenticated?accountName(identity,user):"Preview Mode";
  const email=isAuthenticated?(identity?.email||user?.email||""):"Supabase is not configured";
  const initials=isAuthenticated?accountInitials(name,email):"LP";
  const sessionAction=isAuthenticated
    ? `<div class="account-menu-divider"></div><button class="account-sign-out" type="button" role="menuitem" data-request-sign-out><i class="ph ph-sign-out" aria-hidden="true"></i><span>Sign Out</span></button>`
    : `<p class="account-preview-note"><i class="ph ph-info" aria-hidden="true"></i><span>Account details and Sign Out become active when the app is connected to Supabase.</span></p>`;
  const profileDetails=isAuthenticated
    ? `<dl class="account-details"><div><dt>Display name</dt><dd>${esc(name)}</dd></div><div><dt>Email</dt><dd>${esc(email)}</dd></div><div><dt>Account created</dt><dd>${esc(formatAccountDate(user?.created_at))}</dd></div><div><dt>Last sign in</dt><dd>${esc(formatAccountDate(user?.last_sign_in_at))}</dd></div></dl><p class="dialog-note">Profile editing will be added when account settings are expanded.</p>`
    : `<div class="account-empty-state"><i class="ph ph-user-circle" aria-hidden="true"></i><h3>Preview Mode</h3><p>Supabase is not configured. The account controls remain visible so the application shell can be reviewed locally.</p></div>`;
  return `<div class="account-control"><button class="profile-button" type="button" data-profile-button aria-haspopup="menu" aria-expanded="false" aria-controls="account-menu"><span class="profile-avatar" aria-hidden="true">${initials}</span><span class="sr-only">Open account menu</span><i class="ph ph-caret-down" aria-hidden="true"></i></button><div class="account-menu" id="account-menu" role="menu" data-account-menu hidden><div class="account-summary"><span class="profile-avatar is-large" aria-hidden="true">${initials}</span><div><strong>${esc(name)}</strong><span>${esc(email)}</span></div></div><div class="account-menu-divider"></div><button type="button" role="menuitem" data-open-account-dialog="profile-dialog"><i class="ph ph-user-circle" aria-hidden="true"></i><span>My Profile</span></button><button type="button" role="menuitem" data-open-account-dialog="preferences-dialog"><i class="ph ph-sliders-horizontal" aria-hidden="true"></i><span>Preferences</span></button><button type="button" role="menuitem" data-open-account-dialog="about-dialog"><i class="ph ph-info" aria-hidden="true"></i><span>About Ummiby Companion</span></button>${sessionAction}</div></div><dialog class="account-dialog" id="profile-dialog"><form method="dialog"><div class="dialog-heading"><div><p class="page-kicker">Account</p><h2>My Profile</h2></div><button class="dialog-close" value="cancel" aria-label="Close profile"><i class="ph ph-x" aria-hidden="true"></i></button></div>${profileDetails}</form></dialog><dialog class="account-dialog" id="preferences-dialog"><form method="dialog"><div class="dialog-heading"><div><p class="page-kicker">Account</p><h2>Preferences</h2></div><button class="dialog-close" value="cancel" aria-label="Close preferences"><i class="ph ph-x" aria-hidden="true"></i></button></div><div class="account-empty-state"><i class="ph ph-sliders-horizontal" aria-hidden="true"></i><h3>Your preferences will live here</h3><p>The account-preferences service is connected and ready for future user-controlled settings.</p></div></form></dialog><dialog class="account-dialog" id="about-dialog"><form method="dialog"><div class="dialog-heading"><div><p class="page-kicker">Application</p><h2>About Ummiby Companion</h2></div><button class="dialog-close" value="cancel" aria-label="Close about"><i class="ph ph-x" aria-hidden="true"></i></button></div><div class="about-mark" aria-hidden="true">U</div><dl class="account-details"><div><dt>Version</dt><dd>v${APP_VERSION}</dd></div><div><dt>Account connection</dt><dd>${configured?'Connected':'Preview mode'}</dd></div></dl></form></dialog>${isAuthenticated?`<dialog class="account-dialog is-confirmation" id="sign-out-dialog"><form method="dialog"><div class="dialog-heading"><div><p class="page-kicker">Account</p><h2>Sign out?</h2></div><button class="dialog-close" value="cancel" aria-label="Cancel sign out"><i class="ph ph-x" aria-hidden="true"></i></button></div><p>You’ll return to the login screen. Your saved account data will remain available the next time you sign in.</p><div class="dialog-actions"><button class="button button-secondary" value="cancel">Cancel</button><button class="button button-danger" type="button" data-confirm-sign-out>Sign Out</button></div></form></dialog>`:''}`;
}

export function renderShell({pathname='/home',user=null,identity=null,configured=false,historyView=null,quranHistoryView=null}={}){const active=moduleForPath(pathname),view=viewName(active,pathname),reader=isReader(pathname),banner=bannerMeta(active,pathname);document.documentElement.dataset.theme=active.theme;document.title=`${view} | Ummiby Companion`;return `<div class="app-shell${reader?' is-reading':''}"><header class="brand-panel"><div class="brand-lockup"><div class="brand-mark" aria-hidden="true">U</div><p class="brand-name">Ummiby<br>Companion</p><p class="brand-version">v${APP_VERSION}</p></div></header><section class="module-banner${active.id==='prayer'?' is-prayer-banner':''}${active.id==='names'?' is-names-banner':''}${pathname==='/quran'?' is-quran-home-banner':''}${pathname==='/quran/featured-readings'?' is-quran-featured-banner':''}${pathname==='/quran/al-kahf-friday'?' is-kahf-featured-banner':''}${pathname==='/quran/al-mulk'?' is-mulk-featured-banner':''}${pathname==='/quran/as-sajdah'?' is-sajdah-featured-banner':''}${['/quran/journeys','/quran/reading-units','/quran/surahs'].includes(pathname)?' is-quran-journeys-banner':''}${pathname==='/duaa'?' is-duaa-home-banner':''}${pathname==='/duaa/morning'?' is-duaa-morning-banner':''}${pathname==='/duaa/evening'?' is-duaa-evening-banner':''}${pathname==='/duaa/sleep'?' is-duaa-sleep-banner':''}${pathname==='/duaa/travel'?' is-duaa-travel-banner':''}${pathname==='/duaa/weather'?' is-duaa-weather-banner':''}${pathname==='/duaa/prayer'?' is-duaa-prayer-banner':''}${pathname==='/duaa/collections'?' is-duaa-collections-banner':''}${pathname==='/duaa/history'?' is-duaa-history-banner':''}${pathname==='/duaa/food'?' is-duaa-food-banner':''}${pathname==='/duaa/clothing'?' is-duaa-clothing-banner':''}${pathname==='/duaa/anxiety'?' is-duaa-anxiety-banner':''}${pathname==='/duaa/quranic'?' is-duaa-quranic-banner':''}"><div class="banner-copy"><p class="banner-eyebrow">${esc(banner.eyebrow)}</p><h1 class="banner-title">${esc(banner.title)}</h1><p class="banner-description">${esc(banner.description)}</p></div>${accountControls(user,identity,configured)}</section><aside class="app-sidebar">${sidebar(active)}</aside><main class="module-workspace">${reader?'':moduleNav(active,pathname)}<section class="module-content${active.id==='duaa'?' is-duaa-content':''}${reader?' is-reader-content':''}" id="module-content" tabindex="-1">${active.id==='duaa'?duaaContent(pathname,historyView):active.id==='quran'?quranContent(pathname,quranHistoryView):active.id==='ramadan'?ramadanContent(pathname):active.id==='prayer'?prayerContent(pathname):active.id==='names'?namesContent(pathname):active.id==='fasting'?futureModulePlaceholder(active):`<header class="page-header"><p class="page-kicker">${esc(active.label)}</p><h2 class="page-title">${esc(view)}</h2><p class="page-description">${esc(active.description)}</p></header><div class="card-grid">${placeholders(active)}</div>`}</section></main></div>`}
